  `sectionEapNotes` json DEFAULT NULL,
  `eapJson` json DEFAULT NULL,
  `eapGeneratedAt` timestamp NULL DEFAULT NULL,
  `executiveSummaryJson` json DEFAULT NULL,
  `executiveSummaryGeneratedAt` timestamp NULL DEFAULT NULL,
  `selectedMenu` enum('a','b') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
