INSERT INTO `audits` VALUES (1,1,1,'in_progress','2026-05-13 12:15:30',NULL,NULL,NULL,NULL,NULL,'2026-05-13 12:15:30','2026-06-04 14:59:20',NULL,NULL,NULL,'{\"sections\": [{\"id\": \"s1_purpose\", \"title\": \"Purpose, Scope & Legal Authority\", \"content\": \"This Emergency Action Plan (EAP) for NATHANAEL BERNARDO STA. CATALINA is developed to safeguard the lives of all occupants, including employees, visitors, and contractors, during emergencies. It provides a structured framework for responding to various incidents, ensuring an organized and effective approach that minimizes potential harm and disruption. The plan is designed to facilitate rapid and appropriate actions, from initial notification and evacuation to post-incident recovery, fostering a culture of preparedness and safety within the facility. The EAP also serves as a critical resource for training and drills, reinforcing the knowledge and skills necessary for all personnel to act confidently and competently during an emergency situation. It reflects the facility\'s commitment to maintaining a secure and resilient operational environment for everyone present.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Develop a formal, written Emergency Action Plan (EAP) statement outlining its purpose and scope, ensuring all key elements are clearly articulated.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Ensure that the EAP is made readily available and communicated to all employees, covering who is covered by the plan (employees, visitors, contractors) and their responsibilities.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Establish clear procedures for the annual review and update of the EAP, and whenever changes occur in the facility, personnel, or emergency procedures.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s2_facility_profile\", \"title\": \"Facility Profile & Threat Environment\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility is an office space located at TOMAS CLAUDIO ST, N.A., spanning approximately 900 sq. ft. across two floors within a multi-tenant building. With a maximum occupancy of 100 persons, the facility operates Monday through Friday from 5 AM to 7 PM, with additional evening and after-hours operations, which introduces specific considerations for access control, lighting, and communication. Its multi-tenant nature necessitates coordination with building management and other tenants regarding shared emergency resources and egress routes. Primary access points include the main entrance to the building and specific entrances to the office suite on each floor, requiring robust security protocols.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Conduct a detailed site-specific threat assessment that considers the multi-tenant environment, operating hours, and general office building risks (e.g., fire, medical emergencies, active threats).\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Accurately identify and map all primary and secondary entry/exit points for the facility, including those for general access, emergency egress, and after-hours operations.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Implement appropriate access control measures for the facility, considering its multi-tenant location and evening/after-hours operations, to restrict unauthorized entry.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s3_risk_assessment\", \"title\": \"Risk Assessment Summary\", \"content\": \"Based on the available information, the NATHANAEL BERNARDO STA. CATALINA facility\'s overall risk level is currently unknown, with no critical findings or elevated high-risk categories recorded. This indicates a gap in comprehensive risk identification and analysis, which is crucial for developing a truly effective Emergency Action Plan. The absence of specific threat scenarios or detailed audit findings means that potential vulnerabilities related to the facility\'s multi-tenant occupancy, small footprint, two-floor layout, and evening/after-hours operations have not been adequately assessed. A proactive approach to understanding these risks is essential for informed decision-making and resource allocation to protect occupants and assets.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Conduct a comprehensive, facility-specific risk assessment utilizing a recognized methodology to identify, analyze, and evaluate potential hazards and threats.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Identify specific vulnerabilities related to the multi-tenant building environment, the 2-floor layout, and the facility\'s evening/after-hours operating schedule.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Establish an ongoing process for regular risk identification, assessment, and mitigation strategy development to ensure continuous preparedness.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s4_roles\", \"title\": \"Roles, Responsibilities & ICS Structure\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility operates under a defined Incident Command System (ICS) structure tailored for a medium-sized office environment. At the core of this structure is the Site Lead (functions as Incident Commander per NIMS), who is responsible for overall incident management, decision-making, and coordination with external agencies. The chain of command flows from the Site Lead to the Secondary Lead / Backup, ensuring continuity of operations in the Site Lead\'s absence. Each assigned role, including Emergency Caller (911), Evacuation Coordinator, Accountability Coordinator, External Coordinator / Responder Liaison, and First Aid Coordinator, has distinct responsibilities critical to effective emergency response. For example, the Emergency Caller is tasked with prompt and accurate communication with emergency services, while the Accountability Coordinator ensures all occupants are accounted for post-evacuation. This structure provides a clear framework for delegation, communication, and resource management during an emergency.\", \"recommendations\": [{\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Formally assign individuals to each ICS role, including primary and backup personnel, for the NATHANAEL BERNARDO STA. CATALINA facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Develop detailed job action sheets for each assigned ICS role (Site Lead, Secondary Lead, Emergency Caller, etc.) outlining specific duties and responsibilities before, during, and after an incident.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Conduct initial and recurrent training for all personnel assigned to ICS roles to ensure competency in their designated responsibilities and understanding of the overall command structure.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s5_communication\", \"title\": \"Communication Protocols\", \"content\": \"Effective communication is paramount for a swift and coordinated response at NATHANAEL BERNARDO STA. CATALINA. Internal communication protocols include the use of an audible employee alarm system to alert occupants of an emergency. This system must be capable of producing distinct signals for different types of emergencies, such as evacuation, lockdown, or shelter-in-place, to avoid confusion. Beyond automated systems, designated personnel are responsible for direct notification to specific groups or individuals, ensuring critical information reaches everyone promptly. For external communication, the Emergency Caller (911) is the primary contact for initiating emergency services, providing clear and concise information about the incident and location. The External Coordinator / Responder Liaison will maintain communication with emergency responders upon their arrival, facilitating information exchange and coordination.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Install and maintain an employee alarm system that is distinct in its signal from other alarms and clearly understood by all employees for emergency notification.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Reporting Procedures)\", \"action\": \"Develop and disseminate clear procedures for activating internal and external notifications, including who is responsible for initiating the 911 call and providing critical incident information.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Reporting Procedures)\", \"action\": \"Establish redundant communication methods (e.g., two-way radios, pre-designated phone trees, building-wide PA system coordinated with building management) to ensure connectivity during power outages or system failures, especially for evening/after-hours operations.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s6_evacuation\", \"title\": \"Evacuation Procedures\", \"content\": \"For the NATHANAEL BERNARDO STA. CATALINA facility, clear and accessible evacuation procedures are critical due to its two-floor layout, multi-tenant environment, and 900 sq. ft. size. Primary and secondary evacuation routes must be clearly identified and marked on floor plans posted throughout the premises, ensuring multiple options for egress from each floor. Designated outdoor assembly points, located at a safe distance from the building, are crucial for gathering all evacuees and conducting accountability. The Evacuation Coordinator will direct occupants along the safest routes, while the Accountability Coordinator will be responsible for confirming the presence of all personnel and visitors at the assembly points. Special considerations for individuals needing assistance, such as those with disabilities, must be integrated into these procedures, with pre-assigned assistants or designated areas of refuge.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38 (Evacuation Procedures & Exit Routes)\", \"action\": \"Develop and conspicuously post floor plans that clearly mark primary and secondary evacuation routes, exit doors, and exterior assembly points for both floors of the facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Evacuation Procedures & Exit Routes)\", \"action\": \"Establish clear accountability procedures, including methods for roll calls or sign-in/out sheets, at designated assembly points to ensure all occupants are accounted for after an evacuation.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Evacuation Procedures & Exit Routes)\", \"action\": \"Implement specific procedures and identify resources (e.g., designated assistants, areas of refuge) to ensure safe and timely evacuation for persons with disabilities, in compliance with ADA Title III and Section 504 guidelines.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s7_lockdown\", \"title\": \"Lockdown & Lockout Procedures\", \"content\": \"For the NATHANAEL BERNARDO STA. CATALINA facility, located within a multi-tenant building, clear and distinct lockdown and lockout procedures are paramount. A \'lockdown\' procedure is initiated when a threat is internal or believed to be inside the facility, requiring occupants to secure their current location and prevent access. Given the 900 sq. ft. layout across two floors, occupants should immediately secure individual office spaces by locking doors, blocking entryways with furniture if safe and feasible, and moving away from windows and doors.\\n\\nConversely, a \'lockout\' procedure is implemented when a threat is identified outside the building but in the immediate vicinity, or when an external security perimeter is being established by law enforcement. During a lockout, all exterior doors to the NATHANAEL BERNARDO STA. CATALINA facility and any common areas shared with other tenants must be secured. Business operations may continue, but no one should enter or exit until an \'all clear\' is announced by the Site Lead (functions as Incident Commander per NIMS) or emergency services.\\n\\nCommunication during both lockdown and lockout is critical. The facility\'s designated emergency alarm system should be utilized to signal the initiation of these protocols. Occupants must be trained to recognize distinct signals for each scenario. Following the initial alert, internal communication via designated staff (e.g., using secure messaging apps or internal phone lines) will provide updates and instructions, while maintaining silence and discretion to avoid alerting a potential threat to their location.\\n\\nThe Site Lead (functions as Incident Commander per NIMS) will determine the appropriate protocol based on the threat assessment. All staff must be familiar with the locking mechanisms of all doors, including common area entrances and individual office suites, to ensure rapid and effective securing of the premises. Regular drills will reinforce these procedures and identify any potential vulnerabilities in the facility\'s layout or security measures.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Implement an audible and distinct employee alarm system capable of signaling both lockdown and lockout conditions, ensuring it is heard throughout all occupied areas of the 2-story facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Develop and clearly post step-by-step procedures for securing all doors (internal and external) for both lockdown and lockout, including specific instructions for each floor and shared tenant spaces.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Conduct mandatory training for all staff on recognizing the distinct signals for lockdown/lockout and executing the appropriate door securing and sheltering procedures specific to their location within the NATHANAEL BERNARDO STA. CATALINA facility.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s8_actd\", \"title\": \"ACTD Response Framework\", \"content\": \"The Assess, Commit, Take Action, Debrief (ACTD) framework provides a structured approach for personnel at NATHANAEL BERNARDO STA. CATALINA to make rapid, informed decisions during an active threat incident. This framework is designed to empower individuals by guiding them through critical decision points. The initial \'Assess\' phase requires individuals to quickly evaluate the situation: What is happening? Where is the threat? What is the immediate danger? This involves rapid information gathering from observations, sounds, and any alerts.\\n\\nBased on the assessment, the \'Commit\' phase involves making a definitive decision on the most appropriate response. This is a critical mental shift from observation to action. Options include securing in place (e.g., locking doors, barricading), evacuating the facility, or, as a last resort, preparing to defend. For the NATHANAEL BERNARDO STA. CATALINA facility, given its multi-tenant nature and layout, a rapid assessment of exit availability versus securing an office space will dictate the commitment.\\n\\n\'Take Action\' is the execution of the committed decision. If the commitment is to secure in place, individuals will lock and barricade doors, move away from windows, and maintain silence. If evacuation is chosen, individuals will move quickly and quietly towards the nearest safe exit, following pre-identified routes. If a threat enters their immediate space and escape or securing in place is not possible, the action may involve preparing to defend their lives. These actions must be tailored to the specific office layout, considering the two floors and potential shared common areas.\\n\\nFinally, \'Debrief\' occurs immediately after the incident or when a period of safety allows. This phase involves sharing observations, validating information, and relaying critical details to emergency responders or the Site Lead (functions as Incident Commander per NIMS). It is crucial for ensuring comprehensive understanding of the event, assisting first responders, and supporting post-incident recovery efforts. This ongoing cycle helps refine future responses and enhances overall preparedness.\", \"recommendations\": [{\"basis\": \"ACTD Framework (aligned with CISA active threat preparedness principles)\", \"action\": \"Conduct mandatory annual training sessions for all occupants on the ACTD framework, utilizing facility-specific scenarios and floor plans for NATHANAEL BERNARDO STA. CATALINA.\", \"priority\": \"90 Days\"}, {\"basis\": \"ACTD Framework (aligned with CISA active threat preparedness principles)\", \"action\": \"Develop and distribute clear communication aids (e.g., wallet cards, posters) summarizing the ACTD steps and decision points tailored to the NATHANAEL BERNARDO STA. CATALINA environment.\", \"priority\": \"60 Days\"}, {\"basis\": \"ACTD Framework (aligned with CISA active threat preparedness principles)\", \"action\": \"Integrate ACTD principles into facility-wide drills and exercises, focusing on evaluating rapid decision-making under simulated stress for all occupants.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s9_active_threat\", \"title\": \"Active Threat & Active Shooter Response\", \"content\": \"An active threat or active shooter scenario at NATHANAEL BERNARDO STA. CATALINA demands immediate and decisive action guided by the ACTD framework. Upon identifying or being alerted to an active threat, the first priority is to rapidly assess the situation: Is the threat in your immediate area? What is its location relative to you? What escape routes are available? This initial assessment will drive the subsequent commitment and action.\\n\\nBased on this assessment, individuals must commit to the safest course of action. If a clear and accessible escape path exists that leads away from the threat, occupants should prioritize evacuating the facility. This involves moving quickly and quietly to the nearest safe exit, keeping hands visible for responding law enforcement, and proceeding to a pre-designated external assembly point. For NATHANAEL BERNARDO STA. CATALINA, with its two floors and multiple exits (including common building exits), understanding these routes is crucial.\\n\\nIf evacuation is not a safe or viable option due to the threat\'s proximity or location, the immediate action should be to secure in place. This involves immediately locking and barricading the nearest available room or office door, turning off lights, silencing electronic devices, and positioning oneself out of sight from the door and windows. This denies the threat access and provides a measure of safety. Given the multi-tenant building context, communication with other tenants should be avoided unless it can be done silently and without compromising safety.\\n\\nAs a last resort, if confronted directly by an active threat and unable to escape or secure in place, individuals must be prepared to defend themselves. This is an instinctual response to a life-threatening situation. Following the \'Take Action\' phase, all individuals capable of doing so should debrief by providing critical information to emergency services upon their arrival, including the threat\'s last known location, description, and any casualties. The Site Lead (functions as Incident Commander per NIMS) will coordinate with law enforcement and ensure timely information dissemination.\", \"recommendations\": [{\"basis\": \"ACTD Framework (aligned with CISA active threat preparedness principles)\", \"action\": \"Conduct comprehensive training sessions that include practical exercises on securing in place (locking/barricading doors) and identifying primary and secondary evacuation routes specific to each floor of NATHANAEL BERNARDO STA. CATALINA.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S19\", \"action\": \"Install robust door-locking mechanisms on all office doors and communal spaces within the NATHANAEL BERNARDO STA. CATALINA facility to enhance the ability to deny access during an active threat.\", \"priority\": \"90 Days\"}, {\"basis\": \"ACTD Framework (aligned with CISA active threat preparedness principles)\", \"action\": \"Develop and practice clear communication protocols for alerting staff to an active threat while maintaining discretion, possibly utilizing silent alerts or pre-coded messages.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s10_medical\", \"title\": \"Medical Emergency & Casualty Care\", \"content\": \"During any emergency at NATHANAEL BERNARDO STA. CATALINA, the prompt and effective management of medical emergencies and casualty care is essential. The First Aid Coordinator, along with other trained personnel, will be responsible for providing immediate care within their scope of training. This includes responding to common medical emergencies such as cardiac arrest, severe allergic reactions, choking incidents, and traumatic injuries. All incidents requiring medical attention must be immediately reported to the Emergency Caller (911) for professional medical assistance.\\n\\nFor severe bleeding, which can be life-threatening, the STOP THE BLEED protocol will be implemented. This involves applying direct pressure to the wound, packing the wound with gauze or clean cloth, and applying a tourniquet if the bleeding is on an extremity and direct pressure is ineffective. Bleeding control kits containing tourniquets, hemostatic dressings, and bandages should be strategically located throughout the facility, readily accessible on both floors.\\n\\nIn cases of sudden cardiac arrest, immediate cardiopulmonary resuscitation (CPR) and the use of an Automated External Defibrillator (AED) are critical. While specific AED locations are not currently known for NATHANAEL BERNARDO STA. CATALINA, it is imperative to have them readily available and clearly marked. Personnel trained in CPR and AED use should be able to retrieve and deploy the device within minutes of a cardiac event. The First Aid Coordinator will oversee initial triage efforts, prioritizing care for those with the most critical injuries while awaiting the arrival of EMS.\\n\\nCoordination with arriving EMS personnel is crucial. The External Coordinator / Responder Liaison will meet EMS at a pre-designated safe entry point, provide a clear report of the situation, and guide them to the casualties. A \'warm zone\' or \'casualty collection point\' may be established within the facility, if safe, for consolidating casualties prior to transfer to EMS, ensuring efficient patient transfer and minimizing exposure to any ongoing threat.\", \"recommendations\": [{\"basis\": \"AHA/ILCOR 2020 Guidelines, OSHA 3185\", \"action\": \"Procure and strategically place at least two Automated External Defibrillators (AEDs) within the NATHANAEL BERNARDO STA. CATALINA facility, ensuring at least one is easily accessible on each floor and clearly marked.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38, AHA/ILCOR 2020 Guidelines, OSHA 3185\", \"action\": \"Conduct mandatory CPR/AED and STOP THE BLEED training for all staff, especially the First Aid Coordinator and Secondary Lead / Backup, refreshing certifications annually.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Install fully stocked first aid kits and individual bleeding control kits (including tourniquets and hemostatic gauze) on both floors of the NATHANAEL BERNARDO STA. CATALINA facility, inspecting and replenishing them monthly.\", \"priority\": \"60 Days\"}]}, {\"id\": \"s11_reunification\", \"title\": \"Family Reunification & Accountability\", \"content\": \"Following an emergency at NATHANAEL BERNARDO STA. CATALINA, ensuring the accountability of all occupants and facilitating safe family reunification is a critical post-incident function. Given the facility\'s small size and multi-tenant nature, a primary and secondary off-site reunification location must be pre-identified and communicated to all staff. These sites should be easily accessible, safe from any ongoing threat, and capable of accommodating up to 100 individuals.\\n\\nAccountability procedures begin immediately upon evacuation or securing in place. The Accountability Coordinator is responsible for maintaining an accurate roster of all employees, visitors, and contractors present in the facility during operating hours. Upon reaching the assembly point or reunification site, a systematic roll call and check-in process will be implemented. Any missing individuals will be promptly reported to the Site Lead (functions as Incident Commander per NIMS) and subsequently to emergency services.\\n\\nFamily notification processes will be managed through a designated point of contact, preferably the Site Lead (functions as Incident Commander per NIMS) or an assigned delegate, to ensure consistent and accurate information is shared. A pre-approved communication plan will be utilized to inform families about the incident, the reunification site, and procedures for picking up their loved ones. Strict protocols will be established for the release of individuals, requiring positive identification to prevent unauthorized release.\\n\\nVisitor release protocols will similarly require positive identification by a pre-designated contact or authorized employee. All visitors will be logged in and out of the facility daily to ensure their accountability during an emergency. The reunification process aims to be as compassionate and efficient as possible, reducing stress for families while maintaining order and security.\", \"recommendations\": [{\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Identify and establish agreements with primary and secondary off-site reunification locations suitable for the NATHANAEL BERNARDO STA. CATALINA facility\'s maximum occupancy.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Develop and implement a robust electronic or paper-based accountability system for all employees, visitors, and contractors, ensuring it can be accessed and utilized off-site during an incident.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Train the Accountability Coordinator, Site Lead (functions as Incident Commander per NIMS), and other relevant staff on family notification and reunification procedures, including positive identification protocols for releasing individuals.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s12_media\", \"title\": \"Media & Public Information Management\", \"content\": \"Effective media and public information management is crucial for NATHANAEL BERNARDO STA. CATALINA to control messaging, mitigate misinformation, and maintain public trust during and after an incident. The Site Lead (functions as Incident Commander per NIMS) will serve as the primary spokesperson or designate a qualified individual as the Public Information Officer (PIO) to manage all media inquiries and public communications.\\n\\nAll media inquiries must be directed to the designated spokesperson. No other employee should speak to the media or post information about the incident on social media. Pre-approved messaging protocols will be developed to ensure consistent, accurate, and empathetic communication. Initial statements will focus on acknowledging the incident, confirming that emergency services have been notified, and emphasizing the safety and well-being of occupants, without speculating on causes or details until confirmed.\\n\\nSocial media guidelines will explicitly state that employees are prohibited from posting details, photos, or videos of an ongoing incident. Official communications will be disseminated through approved channels, ensuring that NATHANAEL BERNARDO STA. CATALINA\'s public statements align with the information provided by law enforcement and other emergency responders. The goal is to provide timely, factual updates without compromising ongoing operations or investigations.\\n\\nDuring and after an incident, the designated spokesperson will work closely with the External Coordinator / Responder Liaison to gather accurate information from emergency services and manage the flow of public information. Post-incident, a comprehensive communications strategy will address recovery efforts, support services for employees, and any necessary updates regarding facility status. Maintaining transparent and empathetic communication throughout the process is paramount.\", \"recommendations\": [{\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Crisis Communications)\", \"action\": \"Designate and formally train a primary and secondary spokesperson (PIO) from the NATHANAEL BERNARDO STA. CATALINA staff on crisis communication principles and media interaction protocols.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Crisis Communications)\", \"action\": \"Develop a template for initial media statements and a set of FAQs (Frequently Asked Questions) to address potential public and media inquiries, ensuring alignment with FEMA NIMS/ICS principles.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 1600 (Crisis Communications)\", \"action\": \"Establish clear social media policies for all employees, prohibiting unauthorized posting of information, photos, or videos related to an incident at NATHANAEL BERNARDO STA. CATALINA.\", \"priority\": \"30 Days\"}]}, {\"id\": \"s18_tat\", \"title\": \"Threat Assessment Team (TAT) & Pre-Incident Intervention\", \"content\": \"For NATHANAEL BERNARDO STA. CATALINA, establishing a robust Threat Assessment Team (TAT) is paramount given its office environment, multi-tenant nature, and operations that extend into evening hours. This multidisciplinary team will serve as a proactive measure, identifying, assessing, and managing potential threats before they escalate into incidents. The TAT should comprise key personnel such as the Site Lead (functions as Incident Commander per NIMS), HR representatives, and a designated representative from building management to ensure comprehensive oversight and coordination within the multi-tenant structure.\\n\\nA clear and confidential process for reporting concerning behaviors is essential. Employees should be empowered to report observations related to potential threats, behavioral changes, or direct statements without fear of reprisal, ideally through a designated HR channel or a confidential reporting system. Upon receiving a report, the TAT will convene to conduct a structured risk assessment, evaluating the information collected, considering any previous patterns, and assessing the potential for violence in accordance with established protocols.\\n\\nThe escalation workflow for concerns will move from initial reporting to formal assessment and, if necessary, to intervention. Intervention protocols may encompass a range of strategies, from counseling and de-escalation techniques to disciplinary actions, coordination with law enforcement, or the implementation of protective measures. The primary objective is always to prevent violence, mitigate risk, and ensure the safety and well-being of all occupants at NATHANAEL BERNARDO STA. CATALINA. Regular training for both the TAT and all employees on recognizing and reporting concerning behaviors is crucial for the effectiveness of this program.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Establish a formal, multidisciplinary Threat Assessment Team (TAT) with clearly defined roles and responsibilities.\", \"priority\": \"Immediate\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Develop and implement a clear, confidential process for employees to report concerning behaviors or potential threats.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Create a structured escalation workflow outlining steps from initial concern to threat assessment and intervention protocols.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Conduct initial training for all employees on how to identify and report concerning behaviors to the TAT.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S6, NFPA 3000 (PS) S7\", \"action\": \"Schedule and conduct regular training and drills for the TAT on risk assessment methodologies and intervention strategies.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s19_alarm_system\", \"title\": \"Employee Alarm & Notification System\", \"content\": \"For the NATHANAEL BERNARDO STA. CATALINA office, a robust employee alarm and notification system is critically important to ensure prompt and effective communication during emergencies, particularly given its 2-floor, multi-tenant nature and operations extending into evening hours. The system must possess real-time alert capabilities, capable of reaching all occupants across both floors and throughout common areas, including those working after normal business hours. This ensures that everyone within the facility\'s 100-person capacity receives timely emergency information.\\n\\nTo prevent confusion and facilitate appropriate responses, the system must incorporate distinct audible and visual signals for different types of emergencies. For instance, a unique signal should denote a general evacuation (e.g., fire alarm), while a different, urgent signal (e.g., specific tones, flashing lights, and text messages) should indicate a lockdown directive or a shelter-in-place order. These distinct signals must be easily recognizable and understood by all employees.\\n\\nOngoing maintenance is indispensable for guaranteeing the operational readiness and reliability of the alarm system. Regular maintenance checks should encompass all components, including power sources, battery backups, and the functionality of every notification device throughout the facility. Given the multi-tenant environment, coordination with overall building management regarding any integrated alarm systems is also essential to avoid conflicting signals or delays in communication. \\n\\nConsistent testing of the entire employee alarm and notification system is mandated, with annual drills and documented results, to verify that all components are functioning correctly and that employees are thoroughly familiar with the meaning of each distinct signal and the appropriate actions to take. This includes testing the efficacy of communication across various channels, such as public address systems, email, and SMS, to ensure comprehensive coverage and understanding.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Implement an employee alarm system capable of providing real-time alerts to all personnel within the facility. This is a requirement for employee alarm systems. (OSHA 29 CFR 1910.165)\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Ensure the alarm system utilizes distinct and recognizable signals for different emergency actions, such as evacuation, lockdown, and shelter-in-place, as required by law. (OSHA 29 CFR 1910.165)\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Establish a routine schedule for regular maintenance and inspection of all employee alarm system components to ensure proper operation. (OSHA 29 CFR 1910.165)\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Conduct annual testing of the entire employee alarm and notification system, including all distinct signals, and document the results to verify functionality. (OSHA 29 CFR 1910.165)\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Provide comprehensive training to all employees on the meaning of distinct alarm signals and the appropriate response procedures. (OSHA 29 CFR 1910.165)\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s20_osha_compliance\", \"title\": \"OSHA 29 CFR 1910.38 Compliance Mapping\", \"content\": \"Ensuring full compliance with OSHA 29 CFR 1910.38 is a foundational requirement for the NATHANAEL BERNARDO STA. CATALINA office, as it establishes the minimum criteria for the Emergency Action Plan (EAP). This section provides a direct mapping of how the facility\'s procedures address each of the six mandated elements, tailored for a two-floor, multi-tenant office building with a maximum occupancy of 100 individuals, including those operating during evening hours.\\n\\nThis explicit mapping serves to demonstrate how NATHANAEL BERNARDO STA. CATALINA fulfills its obligations under federal safety standards, ensuring the safety and preparedness of all personnel. It acts as a clear reference for auditors to validate compliance efficiently. The table below details the facility\'s specific actions for each requirement.\\n\\n| OSHA 29 CFR 1910.38 Requirement | NATHANAEL BERNARDO STA. CATALINA\'s Compliance |\\n| :------------------------------------------- | :------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| (1) Procedures for reporting a fire or other emergency | Employees are instructed to dial 911 immediately for life-threatening emergencies or fires. Internal reporting for non-life-threatening incidents is directed to the Site Lead (functions as Incident Commander per NIMS) or Secondary Lead / Backup. All incidents must be reported to the Site Lead (functions as Incident Commander per NIMS) for proper documentation and follow-up. |\\n| (2) Procedures for emergency evacuation, including types of evacuation and exit route assignments | Primary and secondary evacuation routes are clearly marked and posted on each floor of the facility. These routes are a mandatory component of new employee orientation. All exit routes are maintained free from obstructions, well-lit, and lead to designated outdoor assembly points. Evacuation maps are strategically located near exits and in common areas. Annual evacuation drills are conducted to practice these procedures. |\\n| (3) Procedures for employees who remain to operate critical plant operations before they evacuate | As an office facility, NATHANAEL BERNARDO STA. CATALINA does not have critical plant operations that require employees to remain after an emergency alarm. All employees are expected to evacuate immediately and without delay upon activation of the alarm system or direct instruction from the Site Lead (functions as Incident Commander per NIMS). |\\n| (4) Procedures to account for all employees after evacuation | Dedicated Accountability Coordinators are assigned to each designated outdoor assembly point. They are responsible for utilizing pre-assigned employee rosters and conducting immediate roll calls upon arrival at the assembly point. The Site Lead (functions as Incident Commander per NIMS) collects all accountability reports and serves as the primary liaison with external emergency responders. |\\n| (5) Procedures for employees performing rescue or medical duties | The designated First Aid Coordinator and other personnel trained in basic first aid are responsible for providing immediate medical assistance until professional emergency medical services arrive. Rescue operations by employees are strictly limited to those specifically trained in rescue techniques and are only to be attempted if it does not pose an undue risk to the rescuer\'s safety. External emergency services (911) are the primary resource for complex rescue operations and advanced medical care. |\\n| (6) The name or regular job title of employees or departments who can be contacted for further information or explanation of duties under the emergency plan | The Site Lead (functions as Incident Commander per NIMS) and the Secondary Lead / Backup are designated as the primary contacts for any further information or explanation concerning duties under the Emergency Action Plan. Their contact information and roles are clearly documented within the EAP and are accessible to all employees.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Ensure all six required elements of the Emergency Action Plan (EAP) are thoroughly documented and readily accessible to all employees. (OSHA 29 CFR 1910.38)\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Conduct annual training for all employees on the EAP, covering each of the six compliance elements explicitly. (OSHA 29 CFR 1910.38)\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Review and update the EAP annually, or whenever significant changes occur (e.g., facility layout, personnel, processes), to maintain full compliance. (OSHA 29 CFR 1910.38)\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Ensure emergency contact information, evacuation routes, and assembly point maps are prominently posted throughout the facility. (OSHA 29 CFR 1910.38)\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Regularly review and update employee rosters and assigned accountability roles to ensure accuracy and effectiveness of accountability procedures. (OSHA 29 CFR 1910.38)\", \"priority\": \"90 Days\"}]}], \"planTitle\": \"Emergency Action Plan â€” NATHANAEL BERNARDO STA. CATALINA\", \"reviewDate\": \"June 4, 2027\", \"facilitySize\": \"medium\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\"], \"effectiveDate\": \"June 4, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for NATHANAEL BERNARDO STA. CATALINA following a comprehensive workplace safety assessment. The facility has been assessed at an overall risk level of Unknown. Based on the available information, the NATHANAEL BERNARDO STA. CATALINA facility\'s overall risk level is currently unknown, with no critical findings or elevated high-risk categories recorded. This indicates a gap in comprehensive risk identification and analysis, which is crucial for developing a truly effective Emergency Action Plan. The absence of specific threat scenarios or detailed audit findings means that potential vulnerabilities related to the facility\'s multi-tenant occupancy, small footprint, two-floor layout, and evening/after-hours operations have not been adequately assessed. A proactive approach to understanding these risks is essential for informed decision-making and resource allocation to protect occupants and assets.\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000â„¢ (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-04 14:59:21',NULL,NULL,NULL),(2,1,1,'in_progress','2026-05-27 17:30:05',NULL,NULL,NULL,NULL,NULL,'2026-05-27 17:30:05','2026-05-27 17:30:05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(3,2,214,'in_progress','2026-05-28 16:12:54',NULL,NULL,NULL,NULL,NULL,'2026-05-28 16:12:54','2026-05-28 16:12:54',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(4,2,214,'in_progress','2026-05-28 16:21:39',NULL,NULL,NULL,NULL,NULL,'2026-05-28 16:21:39','2026-05-28 16:21:39',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(5,2,214,'in_progress','2026-05-28 17:16:38',NULL,NULL,NULL,NULL,NULL,'2026-05-28 17:16:38','2026-05-28 17:16:38',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(6,2,214,'in_progress','2026-05-28 19:03:05',NULL,NULL,NULL,NULL,NULL,'2026-05-28 19:03:05','2026-05-28 19:03:05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(7,1,1,'in_progress','2026-05-30 15:53:05',NULL,NULL,NULL,NULL,NULL,'2026-05-30 15:53:05','2026-06-03 13:08:13',NULL,NULL,NULL,'{\"sections\": [{\"id\": \"s1_purpose\", \"title\": \"Purpose, Scope & Legal Authority\", \"content\": \"This Emergency Action Plan (EAP) for NATHANAEL BERNARDO STA. CATALINA is developed to ensure the safety and well-being of all individuals within the facility located at TOMAS CLAUDIO ST, N.A. The primary purpose of this plan is to establish clear procedures for responding to various emergencies, including fires, medical incidents, and security threats, thereby minimizing risks to life and property. It outlines the responsibilities of personnel, communication protocols, and specific actions to be taken before, during, and after an incident, ensuring a coordinated and effective response.\\n\\nThe scope of this EAP covers all employees, temporary staff, contractors, visitors, and tenants within the 900 sq. ft., two-story office facility during its operating hours (Monday, 5-7) and any evening/after-hours operations. It applies to all areas of the building, including office spaces, common areas, and designated evacuation routes and assembly points. The plan emphasizes a proactive approach to emergency preparedness, requiring regular training and drills to maintain competency and readiness among all occupants.\\n\\nThis EAP is developed in compliance with regulatory mandates, primarily OSHA 29 CFR 1910.38, which outlines the requirements for emergency action plans, and is further guided by NFPA 3000 (PS) S6, focusing on planning for active assailant incidents, and the principles of FEMA NIMS/ICS for incident management. NATHANAEL BERNARDO STA. CATALINA is committed to fostering a safe working environment and will regularly review and update this plan to reflect current best practices and facility changes. Adherence to this plan is mandatory for all personnel to ensure collective safety and effective emergency response.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(b)(4)\", \"action\": \"Ensure the EAP is readily accessible to all employees, electronically or in hard copy, at all times.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38(f)\", \"action\": \"Conduct initial training for all new employees on the EAP, and refresher training for all employees annually.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Post summary copies of the EAP, including emergency contact numbers and evacuation routes, in conspicuous locations throughout the facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Formally document and review the EAP at least annually, or whenever changes occur in the facility layout, operations, or personnel.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s2_facility_profile\", \"title\": \"Facility Profile & Threat Environment\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility is a two-story office building situated at TOMAS CLAUDIO ST, N.A., encompassing approximately 900 sq. ft. With a maximum occupancy of 100 individuals, the building operates Monday from 5 AM to 7 AM, with acknowledged evening and after-hours operations, indicating potential occupancy outside standard business hours. As a multi-tenant building, coordination with other tenants and the building management regarding shared emergency resources and protocols is critical. The compact size of the facility on two floors necessitates efficient evacuation strategies and clear communication pathways, especially given the shared nature of exit routes and common areas.\\n\\nAccess to the facility typically involves a main entrance on the ground floor, with potential secondary access points or emergency exits on both floors. Given the multi-tenant nature, the building likely has a common lobby or entrance, with individual tenant spaces secured. The TOMAS CLAUDIO ST, N.A. location, while not specified for high-risk categories, should consider general urban or semi-urban threat landscapes. This includes potential for civil disturbances, localized criminal activity, or general security concerns that could impact an office environment. The limited operating hours (Mon 5-7 AM) introduce a unique challenge, as a smaller staff presence during these times might affect immediate response capabilities.\\n\\nWhile no elevated high-risk categories or critical findings were identified in the initial assessment, the multi-tenant configuration itself presents inherent complexities in emergency management, requiring robust coordination with building management and other occupants. The presence of evening/after-hours operations means that a staggered or reduced workforce might be present, potentially affecting the availability of trained personnel. Therefore, a comprehensive understanding of the building\'s overall security infrastructure, including entry controls, surveillance, and shared emergency systems, is vital to mitigate potential threats. Consideration should be given to how building-wide emergencies could impact the facility\'s specific operations and safety plans.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7.3.1\", \"action\": \"Conduct a detailed physical security assessment to identify all access points, potential vulnerabilities, and existing security measures (e.g., locks, alarms, surveillance systems).\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7.3.2\", \"action\": \"Develop and formalize a communication and coordination plan with the building management and other tenants for shared emergency responsibilities and alerts.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7.3.1\", \"action\": \"Assess the specific risks associated with the TOMAS CLAUDIO ST, N.A. location, considering local crime statistics and general threat assessments for urban office environments.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7.5.3\", \"action\": \"Implement enhanced access control measures for the facility, especially during evening and after-hours operations, to prevent unauthorized entry.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s3_risk_assessment\", \"title\": \"Risk Assessment Summary\", \"content\": \"The initial assessment of NATHANAEL BERNARDO STA. CATALINA facility indicates an \'Unknown\' overall risk level, primarily due to the absence of recorded critical findings, high-risk categories at an elevated level, or specific threat scenarios. This lack of detailed information suggests that a comprehensive, structured risk assessment process has not yet been fully implemented or documented for this particular facility. While no immediate \'red flags\' were identified, an \'Unknown\' risk level inherently means that potential vulnerabilities and specific threats relevant to an office environment, particularly within a multi-tenant building, have not been systematically evaluated.\\n\\nThe absence of recorded threat scenarios and critical findings should not be interpreted as an absence of risk, but rather as an incomplete picture of the facility\'s threat landscape. Common vulnerabilities for a 900 sq. ft., two-story office with 100 maximum occupancy, especially in a multi-tenant setting, often include challenges with shared building security, potential for internal security breaches, fire safety concerns, and medical emergencies. Without a formal identification of these, the facility may be inadvertently exposed to preventable incidents or unprepared for foreseeable events.\\n\\nTo move beyond an \'Unknown\' risk level, it is imperative to conduct a thorough and formal risk assessment. This process should systematically identify, analyze, and evaluate potential threats and hazards, considering both the internal environment of NATHANAEL BERNARDO STA. CATALINA and its external context on TOMAS CLAUDIO ST, N.A. The goal is to establish a foundational understanding of the facility\'s unique risk profile, enabling targeted mitigation strategies and ensuring that the Emergency Action Plan is truly responsive to the most probable and impactful risks.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7.1\", \"action\": \"Conduct a comprehensive, documented risk assessment to identify specific hazards, threats (including active threats), and vulnerabilities pertinent to the NATHANAEL BERNARDO STA. CATALINA facility and its location.\", \"priority\": \"Immediate\"}, {\"basis\": \"NFPA 3000 (PS) S7.2.1\", \"action\": \"Categorize and prioritize identified risks based on their likelihood and potential impact to develop targeted mitigation strategies.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7.2.2\", \"action\": \"Engage with relevant stakeholders, including building management and local emergency services, to gather data on common risks in the TOMAS CLAUDIO ST, N.A. area and within multi-tenant buildings.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7.3.3\", \"action\": \"Develop a formal process for regularly reviewing and updating the risk assessment to account for changes in the threat landscape, facility operations, or occupancy.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s4_roles\", \"title\": \"Roles, Responsibilities & ICS Structure\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility has established a clear Incident Command System (ICS) structure to manage emergencies effectively, aligning with FEMA NIMS/ICS principles. This structure ensures that specific roles and responsibilities are assigned to key personnel, providing a coordinated and efficient response during any incident. The designated roles include a Site Lead (functions as Incident Commander per NIMS), a Secondary Lead / Backup, an Emergency Caller (911), an Evacuation Coordinator, an Accountability Coordinator, an External Coordinator / Responder Liaison, and a First Aid Coordinator. Each role is critical for comprehensive incident management, from initial notification to post-incident recovery.\\n\\nThe **Site Lead (functions as Incident Commander per NIMS)** holds overall authority and responsibility for managing the emergency response at the facility. This includes assessing the situation, making critical decisions, establishing objectives, and ensuring the safety of all occupants. The **Secondary Lead / Backup** provides support to the Site Lead and assumes command if the Site Lead is unavailable or incapacitated, ensuring continuity of operations. The **Emergency Caller (911)** is responsible for initiating communication with external emergency services, providing accurate and timely information, and relaying instructions back to the incident site. The **Evacuation Coordinator** directs personnel to safe assembly points and ensures orderly movement during an evacuation, while the **Accountability Coordinator** is responsible for verifying the presence and safety of all occupants post-evacuation.\\n\\nThe **External Coordinator / Responder Liaison** acts as the primary point of contact for external emergency responders, facilitating information exchange and coordinating efforts with agencies such as fire, police, and EMS. The **First Aid Coordinator** is responsible for providing immediate medical assistance to injured individuals until professional medical help arrives. This structured approach, with clearly defined roles and a robust chain of command, is essential for a rapid, organized, and effective response to any emergency at the NATHANAEL BERNARDO STA. CATALINA facility, ensuring that all aspects of an incident are managed systematically.\", \"recommendations\": [{\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Conduct initial NIMS/ICS training for all assigned ICS roles, focusing on their specific duties and the overall incident command structure.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Develop a detailed roster with primary and secondary assignments for each ICS role, ensuring coverage during all operating hours, including evening/after-hours.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Conduct tabletop exercises or drills involving all ICS roles to practice communication protocols and decision-making under various emergency scenarios.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Establish a clear communication plan for the ICS team to ensure seamless information flow between roles during an incident.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s5_communication\", \"title\": \"Communication Protocols\", \"content\": \"Effective communication is paramount during an emergency at NATHANAEL BERNARDO STA. CATALINA, ensuring that all occupants are promptly informed and that external assistance is quickly summoned. The communication protocols outline distinct internal and external notification chains, utilizing various systems to ensure redundancy and reach. For internal notifications, the primary method will involve an audible alarm system designed to alert all personnel simultaneously across both floors of the 900 sq. ft. facility. This system must be capable of broadcasting distinct signals for different types of emergencies, such as evacuation, shelter-in-place, or an immediate threat.\\n\\nUpon activation of an internal alert, the Emergency Caller (911) will be responsible for immediately contacting external emergency services, providing critical information about the incident, including the facility\'s address (TOMAS CLAUDIO ST, N.A.), the nature of the emergency, and the number of people potentially affected. This initial external notification is crucial for dispatching appropriate resources. Simultaneously, the Site Lead (functions as Incident Commander per NIMS) will initiate internal communication with the ICS team, providing updates and directing response actions. Backup communication methods, such as two-way radios for key personnel, pre-programmed emergency contact lists on office phones, and a designated text messaging system, will be established to ensure communication continuity in case of power failure or primary system malfunction.\\n\\nInformation flow will follow a clear hierarchy: the Site Lead (functions as Incident Commander per NIMS) will disseminate information to the ICS team, who will then communicate relevant instructions to their assigned areas or groups. The External Coordinator / Responder Liaison will manage all communications with arriving emergency services, serving as the central point for information exchange. Regular testing of all communication systems, including alarm functionality and backup methods, is essential to confirm their operational readiness. The multi-tenant nature of the building also necessitates a protocol for communicating with building management and other tenants about building-wide emergencies or alarms to ensure coordinated response efforts.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165(b)(2)\", \"action\": \"Install and maintain an employee alarm system capable of providing distinct and recognizable signals for different emergency actions (e.g., evacuation, lockdown).\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.165(b)(3)\", \"action\": \"Ensure that the employee alarm system is clearly audible above ambient noise levels throughout all areas of the 900 sq. ft. facility, including during evening/after-hours operations.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(2)\", \"action\": \"Develop clear, concise instructions for reporting emergencies internally and externally, including specific contact numbers and information to convey to 911.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(2)\", \"action\": \"Establish and regularly test backup communication methods (e.g., two-way radios, mass text notification system) for internal and external communications.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165(b)(5)\", \"action\": \"Provide training to all employees on the types of alarm signals and the appropriate actions to take for each, as well as the procedure for reporting an emergency.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s6_evacuation\", \"title\": \"Evacuation Procedures\", \"content\": \"In the event of an emergency requiring evacuation from NATHANAEL BERNARDO STA. CATALINA, clear and well-practiced procedures are critical to ensure the safe and orderly egress of all 100 maximum occupants from the 900 sq. ft., two-story facility. Primary evacuation routes will be clearly marked and unobstructed, leading directly to designated exits on both the first and second floors. These routes must be routinely inspected to ensure they are free from any impediments. Secondary evacuation routes will also be identified and communicated, providing alternative paths in case a primary route is compromised by fire, smoke, or other hazards. Given the multi-tenant nature, coordination with building management regarding common area egress and overall building evacuation plans is essential.\\n\\nUpon activation of the evacuation alarm, all personnel, visitors, and contractors must immediately proceed to the nearest safe exit. The Evacuation Coordinator, supported by other ICS roles, will guide occupants towards the designated outdoor assembly points. For NATHANAEL BERNARDO STA. CATALINA, specific assembly points located a safe distance from the building at TOMAS CLAUDIO ST, N.A., will be identified, allowing for clear separation from the incident site. These points should be easily accessible and large enough to accommodate all occupants, including those with special needs, and should be communicated to all personnel during training and drills.\\n\\nAccountability is a critical component of the evacuation process. The Accountability Coordinator will be responsible for taking a roll call at the assembly point, using a pre-determined roster of all personnel, including any visitors or contractors. This ensures that everyone who was in the building is accounted for. Procedures for reporting missing persons to the Site Lead (functions as Incident Commander per NIMS) and then to arriving emergency services will be clearly established. Special considerations for individuals with disabilities or those requiring assistance will be incorporated into the evacuation plan, ensuring that no one is left behind. Regular evacuation drills, at least annually, are mandatory to familiarize all occupants with routes, assembly points, and accountability procedures, especially considering the potential for evening/after-hours operations with varying staff levels.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(c)(1); OSHA 29 CFR 1910.38(d)(1)\", \"action\": \"Clearly mark and maintain primary and secondary evacuation routes and exits on both floors of the facility, ensuring they are illuminated and unobstructed.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(3)\", \"action\": \"Designate and clearly mark at least two primary outdoor assembly points located a safe distance from the facility at TOMAS CLAUDIO ST, N.A., and communicate their locations to all employees.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(4)\", \"action\": \"Develop and implement procedures for accounting for all employees and occupants after an evacuation, including specific responsibilities for the Accountability Coordinator.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(f)(2)\", \"action\": \"Conduct evacuation drills at least annually, ensuring all employees are familiar with the alarm, evacuation routes, assembly points, and accountability procedures.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(1); ADA Title III; Section 504\", \"action\": \"Develop specific procedures for assisting employees and visitors with disabilities or those requiring special assistance during an evacuation, in compliance with ADA Title III and Section 504.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s13_training\", \"title\": \"Training, Drills & Exercise Program\", \"content\": \"A comprehensive training, drill, and exercise program is essential to ensure all personnel at NATHANAEL BERNARDO STA. CATALINA are proficient in emergency procedures and their assigned roles. This program will align with NFPA 3000 (PS) sections S10-14, focusing on competency and continuous improvement. Micro-drills, such as communication tests and immediate threat response walk-throughs, should be conducted ongoingly throughout the year to reinforce critical immediate actions. These small-scale exercises are crucial for maintaining a state of readiness within the 900 sq. ft. office space, ensuring rapid, coordinated responses in a multi-tenant environment.\\n\\nExtended drills, including tabletop exercises, functional drills, and full-scale exercises, must be conducted at a minimum annually. Tabletop exercises will involve the leadership team, including the Site Lead (functions as Incident Commander per NIMS), to discuss various threat scenarios pertinent to a multi-tenant office building and validate decision-making processes. Functional drills will simulate specific aspects of the EAP, such as evacuation from the 2-story facility or a lockdown procedure, without full activation of external responders. A full-scale exercise, involving external emergency services where feasible, will test the entire EAP from notification to recovery.\\n\\nAfter-action reviews (AARs) will be conducted immediately following any drill, exercise, or actual incident. These reviews, compliant with OSHA 29 CFR 1910.38 requirements for evaluating EAP effectiveness, will identify strengths, weaknesses, and areas for improvement. All staff, including the Emergency Caller (911), Evacuation Coordinator, and First Aid Coordinator, must receive initial and annual refresher training covering EAP procedures, their specific responsibilities, and the use of emergency equipment. Training materials will be accessible, considering the potential for non-English speaking staff or visitors within the building.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S10-14; OSHA 29 CFR 1910.38\", \"action\": \"Develop and implement a schedule for ongoing micro-drills focusing on immediate threat response, communication, and evacuation paths for the 900 sq. ft. facility.\", \"priority\": \"Immediate\"}, {\"basis\": \"NFPA 3000 (PS) S10-14; OSHA 29 CFR 1910.38\", \"action\": \"Conduct at least one annual extended drill (tabletop, functional, or full-scale) to test comprehensive EAP elements, including coordination with multi-tenant building management.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14; OSHA 29 CFR 1910.38\", \"action\": \"Establish a formal after-action review process for all drills, exercises, and actual incidents, ensuring findings are documented and lead to EAP improvements.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14; OSHA 29 CFR 1910.38\", \"action\": \"Provide initial and annual refresher training for all personnel on the EAP, individual roles, emergency equipment, and specific procedures for the 2-story, multi-tenant building.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s14_continuity\", \"title\": \"Business Continuity & Recovery\", \"content\": \"The Business Continuity and Recovery plan for NATHANAEL BERNARDO STA. CATALINA is designed to ensure the swift restoration of critical business functions following an emergency, minimizing operational disruption and financial impact. Given the office\'s size and multi-tenant nature, identifying and prioritizing essential functions such as IT systems, communication channels, and administrative support is paramount. This plan adheres to NFPA 1600 principles for comprehensive disaster/emergency management and business continuity, ensuring a structured approach to recovery.\\n\\nStrategies for alternate site operations must be established, considering that the primary 900 sq. ft. facility within a multi-tenant building might be inaccessible after an incident. This includes identifying potential temporary workspaces, whether off-site locations or agreements with partner organizations, that can accommodate up to 100 maximum occupants. Data and records recovery protocols are critical, mandating regular backups of essential digital information to secure, off-site locations and maintaining hard copies of vital documents. The plan will also outline procedures for restoring network access and crucial software applications.\\n\\nVendor and supplier continuity is a key component, requiring pre-established relationships and alternative agreements for critical services and supplies to ensure uninterrupted operations. This involves identifying single points of failure within the supply chain and mitigating risks. Recovery priorities will be clearly defined, focusing first on life safety, then property protection, followed by the restoration of core business operations to return the NATHANAEL BERNARDO STA. CATALINA office to full functionality as efficiently as possible, consistent with NFPA 1600 guidance.\", \"recommendations\": [{\"basis\": \"NFPA 1600\", \"action\": \"Conduct a Business Impact Analysis (BIA) to identify and prioritize critical business functions, their dependencies, and required recovery time objectives (RTOs) for the office operations.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Develop a strategy for alternate site operations, including identifying potential temporary locations suitable for the maximum occupancy of 100, and establishing necessary logistical arrangements.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Implement a robust data backup and recovery plan, ensuring regular off-site storage of critical digital records and accessibility protocols.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Review and establish continuity plans with critical vendors and suppliers, identifying alternatives to mitigate supply chain disruptions.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s15_special_populations\", \"title\": \"Special Populations & Accessibility\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA Emergency Action Plan is committed to ensuring the safety and accessibility of all individuals, including those with disabilities, non-English speakers, visitors, and contractors. Procedures are developed in full compliance with ADA Title III and Section 504 of the Rehabilitation Act, ensuring equitable access to emergency information and evacuation routes. Personnel will receive training on assisting individuals with mobility impairments through the 2-story building, considering the need for accessible evacuation routes, and identifying designated areas of refuge if direct evacuation is not immediately possible. Collaboration with multi-tenant building management is vital to ensure common areas and exits are accessible and maintained.\\n\\nFor non-English speakers, emergency communications will be designed to be clear, concise, and where possible, available in multiple languages or through visual aids. Key emergency information, such as evacuation maps and assembly points, will be presented in a universally understandable format. The Site Lead (functions as Incident Commander per NIMS) and Emergency Caller (911) will have access to resources for language assistance if necessary during an emergency, facilitating effective communication with emergency services and affected individuals.\\n\\nProcedures for visitors and contractors include mandatory briefing on key emergency procedures upon arrival, distribution of condensed emergency information, and accounting for their presence during an emergency. The Accountability Coordinator will maintain a visitor log to facilitate accurate headcount during an evacuation. OSHA 29 CFR 1910.38 requires clear communication of emergency procedures to all employees and ensures the EAP is readily available for review. Special consideration is given to individuals who may be unfamiliar with the facility\'s layout, ensuring they receive explicit guidance during an evacuation or lockdown scenario.\", \"recommendations\": [{\"basis\": \"ADA Title III; Section 504 (Rehabilitation Act)\", \"action\": \"Conduct an accessibility audit of the 2-story facility, including common areas shared with other tenants, to identify and address barriers to emergency egress for individuals with disabilities, in accordance with ADA Title III and Section 504.\", \"priority\": \"30 Days\"}, {\"basis\": \"ADA Title III; Section 504 (Rehabilitation Act); OSHA 29 CFR 1910.38\", \"action\": \"Develop and implement procedures for assisting individuals with disabilities during an emergency, including designated staff responsibilities and identification of areas of refuge.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Prepare emergency communications and signage in universally understood formats, considering the need for multilingual information for non-English speakers.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Establish a mandatory briefing process and maintain accurate logs for all visitors and contractors, ensuring they are aware of emergency procedures and accounted for during an event.\", \"priority\": \"Immediate\"}]}, {\"id\": \"s16_maintenance\", \"title\": \"Plan Maintenance & Review Schedule\", \"content\": \"Effective plan maintenance is critical to ensure the NATHANAEL BERNARDO STA. CATALINA Emergency Action Plan (EAP) remains current, accurate, and actionable. This EAP will undergo a formal review annually, with the effective date of June 3, 2026, and a review date of June 3, 2027. This annual review will involve key EAP stakeholders, including the Site Lead (functions as Incident Commander per NIMS) and designated emergency personnel, to assess the plan\'s continued relevance and efficacy in the context of the 900 sq. ft., 2-story multi-tenant office building. This aligns with OSHA 29 CFR 1910.38, which mandates employers to keep their EAPs current and available.\\n\\nBeyond the annual cycle, immediate revisions to the EAP will be triggered by specific events. These trigger events include, but are not limited to, changes in facility layout (e.g., renovations, changes to egress paths), significant personnel changes (especially within assigned ICS roles like the Emergency Caller (911) or Evacuation Coordinator), acquisition of new equipment or technologies impacting emergency response, changes in relevant regulations, or lessons learned from drills, exercises, or actual incidents. Changes in building management or other tenants within the multi-tenant facility that could affect shared emergency procedures also necessitate immediate review.\\n\\nStrict version control will be maintained for the EAP, with each revision clearly marked with a version number and revision date. This ensures that all personnel are working with the most current information. A comprehensive distribution list will ensure that all employees, including the Site Lead, Secondary Lead / Backup, and External Coordinator / Responder Liaison, receive the updated plan. The EAP will be readily accessible to all employees, both electronically and in hard copy, in compliance with OSHA 29 CFR 1910.38 and NFPA 1600 guidance on plan maintenance and review to sustain operational readiness.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38; NFPA 1600\", \"action\": \"Establish a formal annual review process for the EAP, engaging all ICS role holders and key stakeholders, with a scheduled review date of June 3, 2027.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38; NFPA 1600\", \"action\": \"Define and document specific trigger events that necessitate immediate EAP revisions, such as facility changes, personnel changes, and multi-tenant building modifications.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38; NFPA 1600\", \"action\": \"Implement a robust version control system for the EAP, ensuring clear documentation of changes and distribution of the latest version to all personnel on the distribution list.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Maintain an updated distribution list for the EAP, ensuring all employees and relevant external partners receive the current plan and are aware of its accessibility.\", \"priority\": \"Immediate\"}]}, {\"id\": \"s17_appendices\", \"title\": \"Appendices & Supporting Documents\", \"content\": \"The Appendices & Supporting Documents section of the NATHANAEL BERNARDO STA. CATALINA Emergency Action Plan serves as a critical repository of essential information, making the EAP a comprehensive and self-sufficient resource. This section will include an up-to-date contact directory, crucial for rapid response and coordination. This directory must list emergency services (911), key facility staff (including the Site Lead (functions as Incident Commander per NIMS), Secondary Lead / Backup, Emergency Caller (911), Evacuation Coordinator, Accountability Coordinator, External Coordinator / Responder Liaison, and First Aid Coordinator), multi-tenant building management, and critical vendors or contractors. This aligns with OSHA 29 CFR 1910.38\'s requirement for clear contact information for named contact persons.\\n\\nDetailed floor plans for both floors of the 900 sq. ft. office space will be included, clearly marking primary and secondary evacuation routes, assembly points, fire exits, emergency equipment locations (e.g., fire extinguishers, first aid kits, AEDs if applicable), and areas of refuge. These maps are invaluable for both occupants during an emergency and for external responders, aiding in rapid orientation and efficient incident management in accordance with FEMA NIMS/ICS principles. Given the multi-tenant nature, these plans will also highlight points of egress and ingress shared with other occupants.\\n\\nFurthermore, this section will compile comprehensive resource lists, detailing available on-site emergency supplies and equipment, and outlining external resources such as specialized contractors or disaster relief organizations. Any existing mutual aid agreements with other tenants in the building or local businesses will be documented here to facilitate coordinated response efforts. Finally, a list of supporting regulatory references, including all cited OSHA, NFPA, ADA, and FEMA documents, will be provided for easy access and compliance verification, reinforcing the plan\'s foundational basis.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38; FEMA NIMS/ICS\", \"action\": \"Compile and regularly update a comprehensive contact directory including emergency services, all designated ICS role holders, multi-tenant building management, and critical vendors/contractors.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38; FEMA NIMS/ICS\", \"action\": \"Develop and maintain detailed floor plans for both floors, clearly marking evacuation routes, assembly points, emergency equipment, and shared egress points within the multi-tenant facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Create a resource list of on-site emergency supplies and equipment, along with external support resources and any established mutual aid agreements.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Include a comprehensive list of all supporting regulatory references used in the development of the EAP for easy access and compliance verification.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s18_tat\", \"title\": \"Threat Assessment Team (TAT) & Pre-Incident Intervention\", \"content\": \"A crucial component of proactive emergency preparedness for the NATHANAEL BERNARDO STA. CATALINA facility involves the establishment of a multidisciplinary Threat Assessment Team (TAT). This team, as outlined by NFPA 3000 (PS) S6, should comprise key personnel from various departments, including Human Resources, Facility Management, Legal, and designated security or safety professionals. The TAT\'s primary function is to identify, assess, and manage potential threats or concerning behaviors within the workplace before they escalate into critical incidents. This proactive approach aims to mitigate risks to the safety and security of all occupants.\\n\\nThe facility must implement a clear and accessible process for reporting behavioral concerns. This reporting mechanism should encourage employees, tenants, and visitors to submit observations of concerning behaviors, communications, or actions without fear of reprisal. Once a concern is reported, the TAT is responsible for initiating a structured assessment, collecting relevant information, and evaluating the level of threat using established protocols. This systematic review helps determine the appropriate course of action, ranging from minor interventions to formal law enforcement engagement.\\n\\nAn established escalation workflow is essential for ensuring timely and appropriate responses to identified threats. This workflow details the steps the TAT will take, from initial assessment to investigation, and ultimately to intervention. Intervention protocols may include counseling, disciplinary action, security enhancements, or coordination with external agencies such as law enforcement or mental health professionals. The goal is to provide a framework for managing individuals who may pose a risk, ensuring the safety of the NATHANAEL BERNARDO STA. CATALINA environment while also providing support where appropriate.\\n\\nDeveloping and maintaining this comprehensive threat assessment program aligns directly with NFPA 3000 (PS) S7, which emphasizes the importance of conducting thorough risk assessments to identify vulnerabilities and potential threats. Regular training and exercises for the TAT are also vital to ensure their competency in threat recognition, assessment methodologies, and intervention strategies.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S6 (Planning)\", \"action\": \"Form a multidisciplinary Threat Assessment Team (TAT) including representatives from HR, facility management, legal, and security.\", \"priority\": \"Immediate\"}, {\"basis\": \"NFPA 3000 (PS) S7 (Risk Assessment)\", \"action\": \"Develop a formal, confidential behavioral threat reporting process for all employees and tenants at NATHANAEL BERNARDO STA. CATALINA.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7 (Risk Assessment)\", \"action\": \"Establish a clear escalation workflow that outlines steps from concern intake to investigation and intervention protocols.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7 (Risk Assessment)\", \"action\": \"Implement standardized intervention protocols, including resources for internal support and external law enforcement/mental health coordination.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14 (Training/Competency)\", \"action\": \"Conduct annual training and tabletop exercises for the TAT to ensure proficiency in threat assessment and intervention strategies.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s19_alarm_system\", \"title\": \"Employee Alarm & Notification System\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility must implement and maintain an effective employee alarm and notification system to ensure prompt and clear communication during emergencies. As mandated by OSHA 29 CFR 1910.165, this system is critical for alerting all occupants to impending dangers, facilitating timely evacuation, lockdown, or shelter-in-place actions. The system should possess real-time alert capabilities, allowing the Site Lead (functions as Incident Commander per NIMS) or their designee to disseminate critical information quickly and efficiently across both floors of the multi-tenant building.\\n\\nTo prevent confusion and ensure appropriate responses, the alarm system must incorporate distinct signal types for different emergency scenarios, as required by OSHA 29 CFR 1910.165. For instance, a unique sound or message should signify an evacuation order, distinguishing it from a lockdown alert or a directive to shelter-in-place. Clear, concise, and immediately recognizable signals are paramount for employees and tenants to understand the required action without delay, especially given the multi-tenant nature of the building and the varying operating hours.\\n\\nRegular maintenance and testing are indispensable for ensuring the reliability and functionality of the employee alarm system. OSHA 29 CFR 1910.165 requires that all components of the alarm system, including notification devices, power supplies, and control panels, are routinely inspected and tested. These checks prevent system failures during critical moments and ensure that alerts can reach all areas of the 900 sq. ft. facility, including offices and common areas, without obstruction. A documented maintenance schedule and log should be established and diligently followed to comply with regulatory requirements.\\n\\nFurthermore, all employees and tenants must receive comprehensive training on the various alarm signals, their meanings, and the appropriate actions to take for each type of alert. This training, aligned with OSHA 29 CFR 1910.165, should be conducted initially upon hiring or tenancy and reinforced periodically. Understanding the notification system is fundamental to minimizing panic and ensuring an organized and effective emergency response, thereby enhancing overall safety within the NATHANAEL BERNARDO STA. CATALINA facility.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Install or upgrade an employee alarm system with real-time alert capabilities capable of reaching all parts of the NATHANAEL BERNARDO STA. CATALINA facility.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Establish distinct and unambiguous alarm signals for different emergency conditions, such as evacuation, lockdown, and shelter-in-place, as required by OSHA 29 CFR 1910.165.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Develop and implement a documented maintenance schedule for the employee alarm system, including regular inspections and functional testing.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Conduct annual comprehensive testing of the entire employee alarm system to ensure all components are operational and signals are effectively transmitted.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Provide initial and recurrent training to all employees and tenants on the meaning of each distinct alarm signal and the corresponding emergency procedures, as mandated by OSHA 29 CFR 1910.165.\", \"priority\": \"30 Days\"}]}, {\"id\": \"s20_osha_compliance\", \"title\": \"OSHA 29 CFR 1910.38 Compliance Mapping\", \"content\": \"Compliance with OSHA 29 CFR 1910.38 is a foundational requirement for the Emergency Action Plan (EAP) at the NATHANAEL BERNARDO STA. CATALINA facility. This regulation specifies six essential elements that must be included in an EAP to ensure employee safety during emergencies. By systematically mapping the facility\'s procedures against these mandated elements, we can validate the comprehensiveness of the plan and identify any gaps that require attention. This mapping ensures that all personnel, including those involved in evening/after-hours operations and in the multi-tenant environment, are protected.\\n\\nThe following table provides a clear 1:1 mapping of the required OSHA 29 CFR 1910.38 elements to the NATHANAEL BERNARDO STA. CATALINA facility\'s EAP provisions:\\n\\n| OSHA 29 CFR 1910.38 Requirement | NATHANAEL BERNARDO STA. CATALINA EAP Provision |\\n|---|---|\\n| (1) Procedures for reporting a fire or other emergency | Emergency Caller (911) role, direct dial 911 instructions, internal notification protocols to Site Lead (functions as Incident Commander per NIMS) and Secondary Lead / Backup. |\\n| (2) Procedures for emergency evacuation, including types of evacuation and exit route assignments | Detailed evacuation maps for each of the 2 floors, designated primary and secondary exit routes, assembly points, Evacuation Coordinator role, procedures for shelter-in-place and lockdown. |\\n| (3) Procedures for employees who remain to operate critical plant operations before they evacuate | Identification of any critical equipment shutdown procedures (e.g., HVAC, non-essential electrical systems) performed by designated personnel (e.g., Site Lead, Secondary Lead) prior to evacuation. No high-risk categories or critical findings identified at present, so this section is minimal. |\\n| (4) Procedures to account for all employees after evacuation | Accountability Coordinator role, designated assembly areas, use of employee rosters and check-in procedures, communication with Site Lead (functions as Incident Commander per NIMS). |\\n| (5) Procedures for employees performing rescue or medical duties | First Aid Coordinator role, location of first-aid kits and AEDs, basic first aid and CPR training for designated personnel, protocols for assisting individuals with disabilities or special needs during evacuation. |\\n| (6) The name or job title of every employee who may be contacted by employees who need more information about the plan or an explanation of their duties | Site Lead (functions as Incident Commander per NIMS), Secondary Lead / Backup, External Coordinator / Responder Liaison. |\\n\\nThis structured approach ensures that the NATHANAEL BERNARDO STA. CATALINA EAP is not only compliant but also practical and effective for its 100-person maximum occupancy and multi-tenant context. Regular review and updates, as indicated by the June 3, 2027 review date, will maintain its relevance and effectiveness.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Ensure that procedures for reporting all types of emergencies, including fires, are clearly documented and communicated to all employees and tenants.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Develop and widely disseminate clear evacuation procedures, including clearly marked primary and secondary exit routes and designated external assembly points for all floors.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Formally identify and document any specific critical operations that must be performed by designated employees before a full evacuation, if applicable.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Implement a robust employee accountability system to ensure all occupants are accounted for at designated assembly points following an evacuation or incident.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Clearly define and assign roles and responsibilities for employees designated to perform rescue and medical duties, ensuring they receive appropriate training.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Designate specific roles or job titles, such as the Site Lead (functions as Incident Commander per NIMS), as the primary contacts for employee inquiries regarding the EAP.\", \"priority\": \"Immediate\"}]}], \"planTitle\": \"Emergency Action Plan â€” NATHANAEL BERNARDO STA. CATALINA\", \"reviewDate\": \"June 3, 2027\", \"facilitySize\": \"medium\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\"], \"effectiveDate\": \"June 3, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for NATHANAEL BERNARDO STA. CATALINA following a comprehensive workplace safety assessment. The facility has been assessed at an overall risk level of Unknown. The initial assessment of NATHANAEL BERNARDO STA. CATALINA facility indicates an \'Unknown\' overall risk level, primarily due to the absence of recorded critical findings, high-risk categories at an elevated level, or specific threat scenarios. This lack of detailed information suggests that a comprehensive, structured risk assessment process has not yet been fully implemented or documented for this particular facility. While no immediate \'red flags\' were identified, an \'Unknown\' risk level inherently means that potential vulnerabilities and specific threats relevant to an office environment, particularly within a multi-tenant building, have not been systematically evaluated.\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000â„¢ (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-03 13:08:14',NULL,NULL,NULL),(8,2,214,'in_progress','2026-05-31 16:30:00',NULL,NULL,NULL,NULL,NULL,'2026-05-31 16:30:00','2026-05-31 16:30:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(9,2,214,'in_progress','2026-05-31 16:32:43',NULL,NULL,NULL,NULL,NULL,'2026-05-31 16:32:43','2026-05-31 16:32:43',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(10,1,1,'in_progress','2026-06-03 14:41:50',NULL,NULL,NULL,NULL,NULL,'2026-06-03 14:41:50','2026-06-03 14:41:50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(11,1,1,'in_progress','2026-06-04 14:51:29',NULL,NULL,NULL,NULL,NULL,'2026-06-04 14:51:29','2026-06-04 14:51:29',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(12,1,1,'in_progress','2026-06-04 14:53:26',NULL,NULL,NULL,NULL,NULL,'2026-06-04 14:53:26','2026-06-04 14:53:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(13,1,1,'in_progress','2026-06-04 14:53:49',NULL,NULL,NULL,NULL,NULL,'2026-06-04 14:53:49','2026-06-04 14:53:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(14,1,1,'in_progress','2026-06-05 10:58:24',NULL,NULL,NULL,NULL,NULL,'2026-06-05 10:58:24','2026-06-05 10:58:24',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(15,1,1,'in_progress','2026-06-05 15:48:59',NULL,NULL,NULL,NULL,NULL,'2026-06-05 15:48:59','2026-06-05 15:55:57',NULL,NULL,NULL,'{\"sections\": [], \"planTitle\": \"Emergency Action Plan â€” NATHANAEL BERNARDO STA. CATALINA\", \"reviewDate\": \"June 5, 2027\", \"facilitySize\": \"medium\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\"], \"effectiveDate\": \"June 5, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for NATHANAEL BERNARDO STA. CATALINA following a comprehensive workplace safety assessment conducted on June 5, 2026. The plan is aligned with FEMA NIMS/ICS, NFPA 3000â„¢ (PS), OSHA 29 CFR 1910.38, OSHA 29 CFR 1910.165, NFPA 1600, and the ACTD Framework (aligned with CISA active threat preparedness principles).\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000â„¢ (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-05 15:55:57',NULL,NULL,NULL),(16,1,1,'completed','2026-06-05 16:02:07','2026-06-05 16:04:42',0,'Low','{\"Access Control\": {\"weight\": 0.15, \"maxScore\": 0, \"rawScore\": 0, \"riskColor\": \"#22c55e\", \"riskLevel\": \"Low\", \"percentage\": 0}, \"Lighting & Visibility\": {\"weight\": 0, \"maxScore\": 0, \"rawScore\": 0, \"riskColor\": \"#22c55e\", \"riskLevel\": \"Low\", \"percentage\": 0}}',NULL,'2026-06-05 16:02:07','2026-06-09 09:24:54',NULL,NULL,NULL,'{\"sections\": [], \"planTitle\": \"Emergency Action Plan â€” NATHANAEL BERNARDO STA. CATALINA\", \"reviewDate\": \"June 9, 2027\", \"facilitySize\": \"medium\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\"], \"effectiveDate\": \"June 9, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for NATHANAEL BERNARDO STA. CATALINA following a comprehensive workplace safety assessment conducted on June 9, 2026. The plan is aligned with FEMA NIMS/ICS, NFPA 3000â„¢ (PS), OSHA 29 CFR 1910.38, OSHA 29 CFR 1910.165, NFPA 1600, and the ACTD Framework (aligned with CISA active threat preparedness principles).\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000â„¢ (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-09 09:24:55','{\"summary\": \"NATHANAEL BERNARDO STA. CATALINA operates with a low overall risk profile. However, gaps in workplace violence awareness and formal incident reporting procedures reduce staff\'s operational readiness for threat recognition and structured incident control. Addressing these areas strengthens the foundational framework for immediate response capabilities.\", \"generatedAt\": \"2026-06-05T16:05:05.702Z\", \"overallRisk\": \"Low\", \"overallScore\": \"0.0\", \"topPriorities\": [\"Implement annual workplace violence prevention training for all employees, covering threat recognition, de-escalation, and reporting procedures.\", \"Establish formal written incident reporting procedures for all threat types, designating a contact point and clear response timelines.\"], \"leadershipFocus\": \"Leadership should immediately schedule comprehensive workplace violence awareness training for all personnel.\"}','2026-06-05 16:05:06',NULL),(17,1,1,'completed','2026-06-09 09:26:40','2026-06-09 09:33:37',33.3,'Moderate','{\"Parking Areas\": {\"weight\": 0, \"maxScore\": 0, \"rawScore\": 0, \"riskColor\": \"#22c55e\", \"riskLevel\": \"Low\", \"percentage\": 0}, \"Exterior Environment\": {\"weight\": 0.15, \"maxScore\": 24, \"rawScore\": 8, \"riskColor\": \"#84cc16\", \"riskLevel\": \"Moderate\", \"percentage\": 33.3}, \"Lighting & Visibility\": {\"weight\": 0, \"maxScore\": 6, \"rawScore\": 2, \"riskColor\": \"#84cc16\", \"riskLevel\": \"Moderate\", \"percentage\": 33.3}}',NULL,'2026-06-09 09:26:40','2026-06-09 09:44:18',NULL,NULL,NULL,'{\"sections\": [{\"id\": \"s13_training\", \"title\": \"Training, Drills & Exercise Program\", \"content\": \"Given the facility\'s evening/after-hours operations, specific training modules must be developed for personnel working during these times, addressing the unique challenges of reduced staffing and potential access control considerations. Training records, including dates, attendees, and topics covered, will be meticulously maintained to demonstrate compliance and facilitate continuous improvement. The goal is to elevate staff awareness and preparedness, which, alongside robust communication systems and operational policies, are key categories in strengthening the facility\'s overall security posture.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38(f)\", \"action\": \"Develop and implement an annual comprehensive training program covering the EAP, roles, communication protocols, and alarm system use for all employees.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38(f)\", \"action\": \"Conduct annual extended drills, including evacuation or shelter-in-place scenarios, and conduct ongoing micro-drills for specific procedures.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14\", \"action\": \"Establish a formal after-action review process following all drills and exercises to document lessons learned and update EAP components and training materials.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38\", \"action\": \"Provide specialized training for personnel with specific emergency response duties, such as the Site Lead (functions as Incident Commander per NIMS) and First Aid Coordinator.\", \"priority\": \"60 Days\"}]}, {\"id\": \"s14_continuity\", \"title\": \"Business Continuity & Recovery\", \"content\": \"Recovery priorities are tiered, focusing initially on life safety, then property protection, and finally business restoration. This structured approach, guided by NFPA 1600, ensures resources are allocated effectively during the recovery phase. The plan also includes provisions for financial recovery, insurance claims processing, and community support liaison, all vital for a comprehensive return to stability and a reduction of the overall Moderate risk posed by unforeseen events.\", \"recommendations\": [{\"basis\": \"NFPA 1600 (Business Continuity & Recovery)\", \"action\": \"Develop a comprehensive business continuity plan identifying critical functions, their recovery time objectives, and resources needed for restoration.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 1600 (Business Continuity & Recovery)\", \"action\": \"Establish procedures for data and records recovery, including regular backups, off-site storage, and periodic testing of restoration processes.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 1600 (Business Continuity & Recovery)\", \"action\": \"Identify and document potential alternate site operations for NATHANAEL BERNARDO STA. CATALINA, including necessary infrastructure and equipment for critical functions.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 1600 (Business Continuity & Recovery)\", \"action\": \"Create a vendor/supplier continuity strategy, including backup providers and contact information, to ensure access to essential goods and services.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s15_special_populations\", \"title\": \"Special Populations & Accessibility\", \"content\": \"An important aspect of this section is the proactive identification of individuals requiring assistance. This will be done through voluntary disclosure processes, ensuring privacy, and the development of Personal Emergency Evacuation Plans (PEEPs) where appropriate. Regular review and updates of these plans are essential to reflect any changes in occupancy or individual needs, thereby strengthening the facility\'s preparedness and adherence to accessibility standards for its maximum occupancy of 100 people.\", \"recommendations\": [{\"basis\": \"ADA Title III, Section 504 (Rehabilitation Act), OSHA 29 CFR 1910.38\", \"action\": \"Develop and implement specific procedures for assisting individuals with disabilities during emergencies, including identifying needs, designated areas of refuge, and assisted evacuation methods.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(f)\", \"action\": \"Provide initial emergency information to all visitors and contractors upon arrival, covering evacuation routes, assembly points, and emergency contacts.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38(f)\", \"action\": \"Develop communication strategies that accommodate non-English speakers, such as multilingual signage or pre-translated emergency instructions.\", \"priority\": \"90 Days\"}, {\"basis\": \"ADA Title III, Section 504 (Rehabilitation Act)\", \"action\": \"Train emergency personnel, including the Evacuation Coordinator, on proper techniques and considerations for assisting individuals with various disabilities.\", \"priority\": \"60 Days\"}]}, {\"id\": \"s16_maintenance\", \"title\": \"Plan Maintenance & Review Schedule\", \"content\": \"A strict version control system will be implemented to track all revisions, including dates, nature of changes, and individuals responsible for updates. This ensures that all distributed copies are the most current version. The distribution list for the EAP will be regularly updated to ensure all relevant personnel, including the External Coordinator / Responder Liaison and Accountability Coordinator, have access to the latest plan. A clear communication protocol will be established to notify all stakeholders of plan updates and their implications, thereby maintaining the integrity and usability of the EAP as required by NFPA 1600 (Plan Maintenance & Review).\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(e), NFPA 1600 (Plan Maintenance & Review)\", \"action\": \"Conduct a formal annual review of the EAP, involving key stakeholders, to ensure currency, effectiveness, and compliance with OSHA 29 CFR 1910.38 and NFPA 1600.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 1600 (Plan Maintenance & Review)\", \"action\": \"Establish a version control system to track all revisions, dates, changes, and responsible personnel for the EAP.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Define and communicate trigger events for immediate EAP revisions, including facility changes, incidents, and personnel changes in ICS roles.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Maintain an updated distribution list for the EAP and ensure all personnel on the list receive immediate notification of plan updates.\", \"priority\": \"Immediate\"}]}, {\"id\": \"s17_appendices\", \"title\": \"Appendices & Supporting Documents\", \"content\": \"Furthermore, any mutual aid agreements with neighboring multi-tenant facilities or local emergency services will be documented here, outlining predefined support arrangements. Supporting regulatory references, including copies of relevant OSHA standards, NFPA guidelines, and local ordinances, will also be maintained. This ensures that the EAP is not only actionable but also legally compliant and aligned with best practices, forming a comprehensive basis for effective emergency management and reinforcing the facility\'s preparedness posture.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(c)(4), FEMA NIMS/ICS\", \"action\": \"Compile and maintain a comprehensive contact directory including emergency services, key facility staff (Site Lead, Secondary Lead, Emergency Caller), and essential vendors, with primary and alternate contact information.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38(b)(4), FEMA NIMS/ICS\", \"action\": \"Include detailed and updated floor plans for all two floors of NATHANAEL BERNARDO STA. CATALINA, clearly marking exit routes, assembly points, utility shut-offs, and first aid stations.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Develop and maintain a resource list detailing available internal emergency equipment, first aid supplies, and communication tools.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Document any mutual aid agreements with external entities and include relevant supporting regulatory references.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s18_tat\", \"title\": \"Threat Assessment Team (TAT) & Pre-Incident Intervention\", \"content\": \"To effectively address potential threats within the NATHANAEL BERNARDO STA. CATALINA facility, especially given its multi-tenant nature and moderate overall risk level, a multidisciplinary Threat Assessment Team (TAT) must be formally established. This team, comprising representatives from management, human resources, security, and potentially legal counsel, will be responsible for proactively identifying, assessing, and mitigating behavioral concerns that could escalate into violent incidents. This approach aligns with NFPA 3000 (PS) S6, which emphasizes multidisciplinary planning requirements for comprehensive preparedness.\\n\\nThe TAT\'s core function involves developing and implementing a clear behavioral threat reporting process. Employees at NATHANAEL BERNARDO STA. CATALINA must be educated on how to recognize and confidentially report concerning behaviors observed on-site or during evening/after-hours operations. This process should outline various reporting avenues, ensuring accessibility and anonymity where appropriate. The initial intake of concerns will trigger a structured assessment by the TAT, evaluating the nature and severity of the threat.\\n\\nFollowing a thorough assessment, the TAT will initiate an escalation workflow, moving from initial concern to potential intervention. This workflow details specific protocols for addressing threats, which may include direct engagement, mediation, mental health support referrals, security enhancements, or coordination with law enforcement, depending on the risk level. All intervention protocols must prioritize the safety of all occupants within the 900 sq. ft. office space and ensure adherence to legal and ethical guidelines. This systematic risk assessment and management process is a foundational component, consistent with NFPA 3000 (PS) S7.\\n\\nRegular training for all NATHANAEL BERNARDO STA. CATALINA staff on the TAT\'s purpose, reporting procedures, and the importance of early intervention is crucial. Furthermore, the TAT itself will undergo specialized training in threat assessment methodologies to ensure their competency in evaluating risks and implementing appropriate response strategies. Periodic reviews of the TAT\'s effectiveness and protocols will ensure the system remains robust and responsive to the evolving needs of the facility and its 100 maximum occupants.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Formally establish a multidisciplinary Threat Assessment Team (TAT) for NATHANAEL BERNARDO STA. CATALINA, clearly defining roles and responsibilities for each member from management, HR, and security, per NFPA 3000 (PS) S6.\", \"priority\": \"Immediate\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Develop and implement a clear, accessible, and confidential behavioral threat reporting process for all employees within the facility, ensuring alignment with NFPA 3000 (PS) S7 for risk assessment.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Provide initial training to all NATHANAEL BERNARDO STA. CATALINA employees on how to identify and report concerning behaviors, and train TAT members on advanced threat assessment and intervention protocols.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Integrate the TAT\'s pre-incident intervention protocols and reporting mechanisms into the facility\'s overarching Emergency Action Plan (EAP) to ensure a cohesive and comprehensive preparedness strategy.\", \"priority\": \"Long-Term\"}, {\"basis\": \"NFPA 3000 (PS) S6\", \"action\": \"Establish an annual review schedule for the TAT\'s procedures, training effectiveness, and overall performance, making updates as necessary to adapt to facility changes or evolving threat landscapes.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s19_alarm_system\", \"title\": \"Employee Alarm & Notification System\", \"content\": \"The NATHANAEL BERNARDO STA. CATALINA facility must implement a robust employee alarm and notification system capable of providing real-time alerts to all 100 maximum occupants across its two floors, especially considering its multi-tenant building context and potential evening/after-hours operations. This system is critical for rapidly communicating emergency information such as evacuations, lockdowns, or shelter-in-place directives. The system must feature distinct signal types to prevent confusion, clearly differentiating between various emergency responses, as mandated by OSHA 29 CFR 1910.165(b)(4).\\n\\nEffective notification capabilities are paramount, ensuring that all personnel, including those operating during irregular hours, receive immediate and unambiguous instructions. This may involve a combination of audible alarms, visual signals, and electronic notifications (e.g., text, email, internal messaging systems) to ensure reachability. Given the facility\'s location within a multi-tenant building, coordination with building management is essential to ensure seamless integration and avoid conflicting signals or procedures, consistent with the requirements for alarm system functionality under OSHA 29 CFR 1910.165(d).\\n\\nTo ensure continuous readiness, a rigorous schedule for maintenance and testing of the employee alarm system is required. All components, including alarm devices, power supplies, and communication infrastructure, must be regularly inspected and tested to verify functionality and reliability. Detailed records of all maintenance and testing activities must be maintained, demonstrating compliance with OSHA 29 CFR 1910.165(b)(2) and (d)(3).\\n\\nFurthermore, employees must be thoroughly trained on the meaning of each distinct signal and the appropriate response actions. Regular drills, incorporating these distinct signals, will enhance employee recognition and ensure effective response during an actual emergency. Quarterly testing of the alarm system, including an evaluation of employee comprehension, should be conducted to meet the expectations of OSHA 29 CFR 1910.165(b)(5).\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Ensure the NATHANAEL BERNARDO STA. CATALINA facility\'s employee alarm system provides distinct signals for various emergencies (e.g., evacuation, lockdown, shelter-in-place) to prevent confusion, as required by OSHA 29 CFR 1910.165(b)(4).\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Implement a comprehensive system for real-time notification of all employees across both floors and for after-hours operations, utilizing methods that ensure immediate receipt of alerts, in compliance with OSHA 29 CFR 1910.165(d).\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Establish and document a rigorous schedule for maintenance and testing of all employee alarm system components to ensure continuous reliability and functionality, adhering to OSHA 29 CFR 1910.165(b)(2) and (d)(3).\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Conduct quarterly tests of the employee alarm system to verify functionality, and annually train all NATHANAEL BERNARDO STA. CATALINA employees on the meanings of distinct signals and appropriate response actions, as mandated by OSHA 29 CFR 1910.165(b)(5).\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Coordinate with the multi-tenant building management to ensure the facility\'s alarm system integrates with or complements the building-wide emergency notification system, ensuring comprehensive coverage under OSHA 29 CFR 1910.165.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s20_osha_compliance\", \"title\": \"OSHA 29 CFR 1910.38 Compliance Mapping\", \"content\": \"The Emergency Action Plan (EAP) for NATHANAEL BERNARDO STA. CATALINA must explicitly address all six required elements of OSHA 29 CFR 1910.38 to ensure comprehensive compliance and preparedness for its 100 maximum occupants. This mapping demonstrates how the facility\'s existing ICS roles and operational policies fulfill these critical federal requirements, providing a clear framework for emergency response and employee safety within the 900 sq. ft. multi-tenant office space. The following table details this direct mapping:\\n\\n| OSHA 29 CFR 1910.38 Requirement | Facility\'s Emergency Action Plan (EAP) Mapping |\\n| :-------------------------------- | :--------------------------------------------- |\\n| **(1) Reporting procedures** | Employees are instructed to contact the Emergency Caller (911) directly for immediate threats and to notify the Site Lead (functions as Incident Commander per NIMS) or Secondary Lead / Backup of all incidents upon activation of the EAP. A formal incident reporting form is used for post-incident documentation. |\\n| **(2) Evacuation procedures and exit routes** | Clear, posted evacuation plans identify primary and secondary exit routes for all areas of both floors of the NATHANAEL BERNARDO STA. CATALINA facility. The Evacuation Coordinator is responsible for directing personnel to assembly points. Procedures include consideration for persons needing assistance, ensuring compliance with ADA Title III and Section 504 requirements. |\\n| **(3) Critical operations before evacuation** | Given the office nature of NATHANAEL BERNARDO STA. CATALINA, there are typically no critical operations that must be performed before evacuation. If any essential systems require controlled shutdown (e.g., secure data, power-down non-essential equipment), these are outlined in specific job-aid annexes for designated personnel. |\\n| **(4) Employee accountability** | The Accountability Coordinator is responsible for ensuring all employees, visitors, and contractors are accounted for at designated assembly points following an evacuation. This includes cross-referencing daily occupancy logs and employee rosters, particularly important during evening/after-hours operations. |\\n| **(5) Rescue and medical duties** | The First Aid Coordinator is designated to administer basic first aid and coordinate with external emergency medical services. All employees are trained on how to assist individuals requiring assistance to evacuate. The facility does not have dedicated rescue personnel but relies on external emergency responders. AHA/ILCOR 2020 and OSHA 3185 guidelines for AED use and CPR are incorporated into relevant training. |\\n| **(6) Named contact person by role/title** | The Site Lead (functions as Incident Commander per NIMS) serves as the primary contact person for coordination with emergency services and internal decision-making. The Secondary Lead / Backup is designated to assume this role in the absence of the Site Lead. |\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Conduct an annual review and update of the NATHANAEL BERNARDO STA. CATALINA EAP to ensure continued full alignment with all six required elements of OSHA 29 CFR 1910.38, reflecting any changes in facility operations, personnel, or potential threats.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Provide annual training for all NATHANAEL BERNARDO STA. CATALINA employees on the EAP, specifically covering reporting procedures, evacuation routes, critical operations before evacuation (if applicable), and accountability protocols as required by OSHA 29 CFR 1910.38.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Ensure that all designated ICS roles (Site Lead, Emergency Caller, Evacuation Coordinator, Accountability Coordinator, First Aid Coordinator) receive specific and documented training relevant to their duties under the EAP, as outlined by OSHA 29 CFR 1910.38.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Develop clear, written procedures for any specific critical operations that might precede an evacuation, even if minimal for an office environment, and integrate them into the EAP as required by OSHA 29 CFR 1910.38(c)(3).\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Distribute the EAP, including evacuation plans and designated roles, to all employees and make it readily accessible at NATHANAEL BERNARDO STA. CATALINA, ensuring compliance with OSHA 29 CFR 1910.38(e).\", \"priority\": \"30 Days\"}]}], \"planTitle\": \"Emergency Action Plan â€” NATHANAEL BERNARDO STA. CATALINA\", \"reviewDate\": \"June 9, 2027\", \"facilitySize\": \"medium\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\"], \"effectiveDate\": \"June 9, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for NATHANAEL BERNARDO STA. CATALINA following a comprehensive workplace safety assessment conducted on June 9, 2026. The plan is aligned with FEMA NIMS/ICS, NFPA 3000â„¢ (PS), OSHA 29 CFR 1910.38, OSHA 29 CFR 1910.165, NFPA 1600, and the ACTD Framework (aligned with CISA active threat preparedness principles).\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000â„¢ (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-09 09:44:19','{\"summary\": \"A moderate risk profile defines this office location, with primary exposures identified in Exterior Environment and Lighting & Visibility. These conditions compromise natural surveillance and delay threat recognition, forcing staff into reactive postures rather than proactive incident control. Addressing these foundational elements immediately strengthens perimeter security and enhances situational awareness.\", \"generatedAt\": \"2026-06-09T09:33:45.755Z\", \"overallRisk\": \"Moderate\", \"overallScore\": \"33.3\", \"topPriorities\": [\"Conduct a CPTED assessment of the exterior environment to enhance natural surveillance and harden perimeter access points.\", \"Implement an immediate lighting audit for all exterior and internal high-risk areas, replacing deficient fixtures to boost visibility.\"], \"leadershipFocus\": \"Leadership should schedule a comprehensive CPTED assessment and initiate the lighting audit within 30 days.\"}','2026-06-09 09:33:46',NULL),(18,1,1,'in_progress','2026-06-09 09:34:05',NULL,NULL,NULL,NULL,NULL,'2026-06-09 09:34:05','2026-06-09 09:34:05',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(19,1,1,'in_progress','2026-06-10 09:58:08',NULL,NULL,NULL,NULL,NULL,'2026-06-10 09:58:08','2026-06-10 09:58:08',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(27,27,1,'in_progress','2026-06-10 21:33:00',NULL,NULL,NULL,NULL,'Initial audit created during facility onboarding for Testing Facility.','2026-06-10 21:33:00','2026-06-10 21:50:10',NULL,NULL,NULL,NULL,NULL,'{\"summary\": \"This retail facility maintains a low overall risk profile. Gaps in workplace violence awareness training and formal incident reporting procedures reduce staff\'s ability to recognize and de-escalate threats, hindering a timely, documented incident response. Immediately fortify these foundational controls to ensure consistent staff readiness.\", \"generatedAt\": \"2026-06-10T21:49:28.033Z\", \"overallRisk\": \"Low\", \"overallScore\": \"0.0\", \"topPriorities\": [\"Implement annual workplace violence prevention training for all employees.\", \"Establish formal written incident reporting procedures covering all threat types.\"], \"leadershipFocus\": \"Leadership should direct the immediate implementation of annual workplace violence prevention training for all personnel.\"}','2026-06-10 21:49:28',NULL),(28,13,1,'completed','2026-06-10 21:33:18','2026-06-10 21:46:57',0,'Low','{}',NULL,'2026-06-10 21:33:18','2026-06-10 21:47:02',NULL,NULL,NULL,NULL,NULL,'{\"summary\": \"This facility presents a low overall risk posture, with foundational controls largely effective. Critical elements requiring immediate attention include consistent workplace violence awareness training and a formalized incident reporting structure. Strengthening these areas fortifies staff situational awareness and ensures predictable incident control mechanisms.\", \"generatedAt\": \"2026-06-10T21:47:02.280Z\", \"overallRisk\": \"Low\", \"overallScore\": \"0.0\", \"topPriorities\": [\"Implement mandatory annual workplace violence awareness training for all staff, documenting attendance.\", \"Establish a formal, comprehensive incident reporting procedure covering all threat types and response timelines.\"], \"leadershipFocus\": \"Leadership should immediately initiate the development and deployment of a formal incident reporting procedure.\"}','2026-06-10 21:47:02',NULL),(29,27,1,'completed','2026-06-10 21:33:23','2026-06-10 21:46:22',0,'Low','{\"Parking Areas\": {\"weight\": 0, \"maxScore\": 0, \"rawScore\": 0, \"riskColor\": \"#22c55e\", \"riskLevel\": \"Low\", \"percentage\": 0}}',NULL,'2026-06-10 21:33:23','2026-06-10 21:47:12',NULL,NULL,NULL,NULL,NULL,'{\"summary\": \"This facility maintains a low overall risk profile, with specific gaps identified in Workplace Violence Training and Incident Reporting Procedures. These deficiencies limit staff threat recognition and compromise timely incident control by delaying structured response and documentation. Addressing these areas strengthens proactive safety capabilities and ensures systematic incident management.\", \"generatedAt\": \"2026-06-10T21:47:12.333Z\", \"overallRisk\": \"Low\", \"overallScore\": \"0.0\", \"topPriorities\": [\"Implement comprehensive Workplace Violence Awareness Training for all employees.\", \"Establish formal, documented Incident Reporting Procedures for all threat types.\"], \"leadershipFocus\": \"Leadership should schedule immediate implementation of annual workplace violence awareness training for all personnel.\"}','2026-06-10 21:47:12',NULL),(30,27,1,'in_progress','2026-06-10 23:07:54',NULL,NULL,NULL,NULL,NULL,'2026-06-10 23:07:54','2026-06-10 23:15:00',NULL,NULL,NULL,'{\"sections\": [{\"id\": \"s1_purpose\", \"title\": \"Purpose, Scope & Legal Authority\", \"content\": \"This Emergency Action Plan (EAP) is established for the Testing Facility located at Carmel Village Phase 1, Calamba, 4027 Laguna, Philippines. Its primary purpose is to ensure the safety and well-being of all personnel, visitors, and contractors within the 11 sq. ft., three-floor facility during emergency situations. The plan outlines clear procedures for responding to various emergencies, facilitating swift and organized actions to minimize harm, protect assets, and ensure continuity of essential operations.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(b)(5)\", \"action\": \"Ensure that the EAP is readily accessible to all employees, for instance, in a common area or digitally, in accordance with OSHA requirements.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Conduct an annual review and update of this EAP, and whenever changes occur in the facility layout, operations, or emergency response personnel.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s2_facility_profile\", \"title\": \"Facility Profile & Threat Environment\", \"content\": \"The Testing Facility is a micro-sized retail space spanning 11 square feet across three floors, located within a multi-tenant building at Carmel Village Phase 1, Calamba, 4027 Laguna, Philippines. With a maximum occupancy of two individuals, the facility operates seven days a week from 9:00 AM to 5:00 PM. Its compact size and limited occupancy simplify certain emergency responses but also necessitate highly efficient procedures given its multi-tenant environment.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"As the facility operates within a multi-tenant building, establish formal communication and coordination protocols with the building management and other tenants regarding shared emergency procedures, alarm systems, and evacuation routes to address potential moderate concerns (score 2) related to external coordination.\", \"priority\": \"30 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Maintain updated contact information for building management and local emergency services to ensure efficient external communication during an incident, addressing any minor concerns (score 1) regarding communication gaps.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s3_risk_assessment\", \"title\": \"Risk Assessment Summary\", \"content\": \"The comprehensive audit for the Testing Facility indicated an \'Overall Risk Level: Low\' (0-20%), with \'No Critical Findings\' recorded. While specific category scores were not provided, this low-risk designation suggests that foundational security and preparedness elements are largely in place. Categories such as Exterior Environment, Access Control, and Doors & Locks likely scored low (0-1), indicating a robust baseline posture for physical security, contributing significantly to the overall low-risk profile.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Given the \'Low\' overall risk level, prioritize regular, low-impact drills to reinforce emergency procedures, particularly for evacuation and communication, to proactively address any minor concerns (score 1) in Staff Awareness & Training.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S7\", \"action\": \"Implement a schedule for quarterly internal reviews of operational policies and emergency procedures to identify potential minor concerns (score 1) before they escalate, ensuring continuous improvement in preparedness.\", \"priority\": \"Long-Term\"}]}, {\"id\": \"s4_roles\", \"title\": \"Roles, Responsibilities & ICS Structure\", \"content\": \"Due to the micro size and maximum occupancy of two individuals, the Testing Facility\'s Incident Command System (ICS) structure is streamlined to ensure rapid decision-making and action. The primary roles include the Site Lead (functions as Incident Commander per NIMS), who assumes overall command, directs emergency response, and makes critical decisions. Supporting roles are the Emergency Caller (911) responsible for contacting external emergency services, and the Evacuation Coordinator, ensuring personnel accountability during egress.\", \"recommendations\": [{\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Assign primary and at least one backup individual for each ICS role (Site Lead (functions as Incident Commander per NIMS), Emergency Caller (911), Evacuation Coordinator) to ensure continuity of operations, addressing a potential minor concern (score 1) in personnel availability.\", \"priority\": \"90 Days\"}, {\"basis\": \"FEMA NIMS / ICS\", \"action\": \"Provide specialized training for all personnel assigned to ICS roles, focusing on their specific duties and the overall chain of command, to maintain a high level of competency and address any minor concerns (score 1) in staff awareness.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s5_communication\", \"title\": \"Communication Protocols\", \"content\": \"Effective communication is paramount for a micro-facility during an emergency. Internal communication among the two occupants will primarily involve verbal alerts and direct instructions from the Site Lead (functions as Incident Commander per NIMS). External communication protocols dictate that the Emergency Caller (911) is responsible for promptly notifying local emergency services. Given the multi-tenant environment, coordination with building management\'s alarm systems and communication channels is also critical. Backup communication methods, such as personal mobile phones, are essential to ensure uninterrupted communication.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.165(b)(2)\", \"action\": \"Ensure the facility has an operational employee alarm system that provides a distinct and recognizable signal for different types of emergencies, addressing any moderate concern (score 2) regarding immediate threat notification.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(4)\", \"action\": \"Establish clear procedures for contacting emergency services (e.g., dialing 911 or local equivalent) and maintaining an updated list of internal and external emergency contacts readily accessible to all personnel, addressing any minor concern (score 1) in reporting efficiency.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(4), OSHA 29 CFR 1910.165\", \"action\": \"Integrate the facility\'s emergency communication plan with the multi-tenant building\'s overall communication systems and protocols, including shared alarm systems, to address a potential moderate concern (score 2) in coordination.\", \"priority\": \"30 Days\"}]}, {\"id\": \"s6_evacuation\", \"title\": \"Evacuation Procedures\", \"content\": \"Given the Testing Facility\'s compact 11 sq. ft. size across three floors within a multi-tenant building, evacuation procedures must be direct and well-rehearsed. Primary evacuation routes will utilize the most direct and unobstructed paths to designated exits, typically aligning with the building\'s main egress pathways. Secondary routes should be identified in case the primary path is compromised. A primary outdoor assembly point, distinct from the building\'s immediate vicinity, will be established for personnel accountability. Due to the minimal occupancy of two, accountability procedures will be straightforward, typically involving visual confirmation at the assembly point.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38(c)(2), OSHA 29 CFR 1910.36\", \"action\": \"Clearly mark primary and secondary evacuation routes and exits with illuminated signs, especially given the multi-floor layout, addressing any minor concern (score 1) regarding route clarity.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(c)(3)\", \"action\": \"Designate a primary and alternate outdoor assembly point for the facility\'s occupants, ensuring they are a safe distance from the building and readily identifiable to address any minor concern (score 1) in safe gathering.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38(e)\", \"action\": \"Conduct regular evacuation drills at least annually to familiarize all occupants with primary and secondary routes, assembly points, and accountability procedures, addressing any minor concern (score 1) in staff preparedness.\", \"priority\": \"Long-Term\"}]}], \"planTitle\": \"Emergency Action Plan -- Testing Facility\", \"reviewDate\": \"June 10, 2027\", \"facilitySize\": \"micro\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Emergency Caller (911)\", \"Evacuation Coordinator\"], \"effectiveDate\": \"June 10, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for Testing Facility following a comprehensive workplace safety assessment. The facility has been assessed at an overall risk level of Low. The comprehensive audit for the Testing Facility indicated an \'Overall Risk Level: Low\' (0-20%), with \'No Critical Findings\' recorded. While specific category scores were not provided, this low-risk designation suggests that foundational security and preparedness elements are largely in place. Categories such as Exterior Environment, Access Control, and Doors & Locks likely scored low (0-1), indicating a robust baseline posture for physical security, contributing significantly to the overall low-risk profile.\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000 (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-06-10 23:15:00','{\"summary\": \"This retail testing facility maintains a low overall risk profile, with specific exposures in workplace violence preparedness and formal incident reporting. These gaps hinder staff\'s ability to rapidly recognize early threat indicators and execute standardized incident control actions. Focused attention on foundational staff training and clear procedural frameworks is required.\", \"generatedAt\": \"2026-06-10T23:13:59.333Z\", \"overallRisk\": \"Low\", \"overallScore\": \"0.0\", \"topPriorities\": [\"Implement annual workplace violence awareness training for all employees.\", \"Establish formal procedures for reporting all threat types, including clear roles and timelines.\"], \"leadershipFocus\": \"Leadership should immediately schedule the implementation of comprehensive workplace violence awareness training.\"}','2026-06-10 23:13:59',NULL),(31,28,1,'in_progress','2026-06-12 02:45:03',NULL,NULL,NULL,NULL,'Initial audit created during facility onboarding for Madison Square Garden.','2026-06-12 02:45:03','2026-06-12 02:45:03',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(32,29,6205,'in_progress','2026-07-06 17:23:28',NULL,NULL,NULL,NULL,'Initial audit created during facility onboarding for Freedom HR Solutions.','2026-07-06 17:23:28','2026-07-06 17:23:28',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(33,30,1,'in_progress','2026-07-27 10:58:07',NULL,NULL,NULL,NULL,'Initial audit created during facility onboarding for TEST 1.','2026-07-27 10:58:07','2026-07-27 11:01:17',NULL,NULL,NULL,'{\"sections\": [{\"id\": \"s7_lockdown\", \"title\": \"Lockdown & Lockout Procedures\", \"content\": \"For TEST 1, a multi-tenant, 24-floor government facility, robust lockdown and lockout procedures are essential to protect the 240 maximum occupants. A `lockdown` protocol is initiated when there is an immediate threat *inside* the facility or in close proximity, requiring occupants to shelter in place within their secure areas. A `lockout` protocol is used when there is a threat *outside* the facility but not an immediate danger to occupants, focusing on securing exterior access points and limiting movement within the building. These procedures must be clearly distinguished and understood by all personnel to ensure the appropriate response is triggered based on the nature and proximity of the threat.\\n\\nUpon initiation, the Site Lead (functions as Incident Commander per NIMS) will direct the activation of either a lockdown or lockout. Communication during these events is paramount; the employee alarm system, supplemented by internal communication channels, must clearly and distinctly signal the specific protocol required. For a lockdown, occupants on each of the 24 floors, especially Floor / Area Coordinators, are responsible for immediately securing all entry points to their designated areas, moving away from windows and doors, and maintaining silence. For a lockout, staff will ensure all exterior doors are secured, restrict entry for non-essential personnel, and continue operations while remaining vigilant.\\n\\nDoor securing procedures for TEST 1 must account for the multi-tenant environment. This involves ensuring all internal office doors are lockable from the inside. For common areas, pre-designated secure zones should be identified on each floor where occupants can gather and shelter. Regular drills are critical to evaluate the effectiveness of these procedures, ensuring that security measures can be swiftly and effectively implemented across all floors and tenants, minimizing exposure to potential threats. The Site Lead (functions as Incident Commander per NIMS) will determine when it is safe to lift either protocol, ensuring coordinated communication to all occupants.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Develop and document distinct, step-by-step lockdown and lockout procedures tailored to TEST 1\'s multi-tenant, 24-floor layout, including specific actions for Floor / Area Coordinators.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.165\", \"action\": \"Implement an employee alarm system capable of communicating distinct signals for lockdown versus lockout scenarios, ensuring clarity for all 240 occupants across 24 floors.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Conduct quarterly drills for both lockdown and lockout procedures, followed by After-Action Reviews to identify and address any procedural or structural deficiencies in securing the facility.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s8_actd\", \"title\": \"ACTD Response Framework\", \"content\": \"The ACTD (Assess, Commit, Take Action, Debrief) framework provides a structured approach for critical decision-making during active threat incidents at TEST 1, a 24-floor government facility. This framework empowers the Site Lead (functions as Incident Commander per NIMS) and all personnel to make informed, rapid decisions under duress. The `Assess` phase involves quickly evaluating the nature, location, and severity of the threat, leveraging information from the Emergency Caller (911), Floor / Area Coordinators, and any available surveillance systems. This initial assessment guides the subsequent commitment to a course of action.\\n\\nDuring the `Commit` phase, the Site Lead (functions as Incident Commander per NIMS) must decide on the most appropriate response strategy based on the assessment. This could involve initiating a full facility lockdown, a partial floor evacuation, or preparing for an engagement with the threat. This commitment must be communicated clearly and concisely to all relevant personnel, including the Secondary Lead / Backup, Evacuation Coordinator, and Floor / Area Coordinators, to ensure a unified response across the multi-tenant building\'s 24 floors. Decision-making should prioritize the safety of all 240 occupants.\\n\\nThe `Take Action` phase involves the immediate implementation of the committed strategy. This may include securing perimeters, directing occupants to designated safe areas, or, as a last resort, defending against the threat. All actions must be coordinated with the External Coordinator / Responder Liaison for seamless integration with external emergency services. Post-incident, the `Debrief` phase is critical. It involves a structured review of the incident, evaluating the effectiveness of the response, identifying lessons learned, and implementing corrective actions to enhance future preparedness. This iterative process ensures continuous improvement in TEST 1\'s active threat response capabilities.\", \"recommendations\": [{\"basis\": \"ACTD Framework\", \"action\": \"Integrate the ACTD framework into all active threat training programs for TEST 1 personnel, emphasizing rapid assessment and decision-making for the Site Lead (functions as Incident Commander per NIMS) and Floor / Area Coordinators.\", \"priority\": \"30 Days\"}, {\"basis\": \"ACTD Framework\", \"action\": \"Develop detailed scenarios specific to TEST 1\'s multi-tenant, 24-floor environment for tabletop exercises, focusing on `Assess` and `Commit` phases within the ACTD framework.\", \"priority\": \"90 Days\"}, {\"basis\": \"ACTD Framework\", \"action\": \"Establish a formal `Debrief` protocol following any incident or drill to ensure lessons learned are documented and integrated into revised EAPs and training modules.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s9_active_threat\", \"title\": \"Active Threat & Active Shooter Response\", \"content\": \"In the event of an active threat or active shooter incident at TEST 1, a 24-floor government facility, the response protocols must be meticulously planned to protect the maximum occupancy of 240 individuals. Based on the ACTD model, the immediate priority is to `Assess` the situation, determine the location of the threat relative to occupants, and rapidly `Commit` to the most appropriate course of action. The Site Lead (functions as Incident Commander per NIMS), supported by the Emergency Caller (911) and Floor / Area Coordinators, must gather real-time intelligence to inform this critical decision, recognizing the complexities introduced by the facility\'s 24 floors and multiple tenants.\\n\\nUpon `Commitment` to a response, occupants will `Take Action` using one of three primary strategies tailored to TEST 1\'s layout and access points. The first strategy involves prompt evacuation away from the threat, utilizing designated egress routes to a safe assembly point outside the facility. This is particularly relevant if the threat is contained to a specific floor or area, allowing others to safely exit the building. The Evacuation Coordinator and Floor / Area Coordinators are crucial in guiding this process across all 24 floors, ensuring clear pathways and accounting for all personnel.\\n\\nThe second strategy, when evacuation is not feasible, is to seek secure shelter within the facility. This involves moving to a secure, lockable room, barricading the door, turning off lights, silencing electronic devices, and remaining out of sight. The multi-tenant nature of TEST 1 necessitates clear communication regarding designated secure areas. As a last resort, if confronted by an active threat and unable to escape or shelter effectively, individuals should be prepared to defend themselves. This involves employing defensive tactics with conviction to disrupt and incapacitate the threat. All actions should be followed by a comprehensive `Debrief` to refine procedures and ensure continuous improvement in preparedness, aligning with NFPA 3000 (PS) S19.\", \"recommendations\": [{\"basis\": \"ACTD Framework, NFPA 3000 (PS) S19\", \"action\": \"Develop floor-specific protocols for active threat response, mapping secure shelter locations and primary/secondary evacuation routes for each of TEST 1\'s 24 floors.\", \"priority\": \"30 Days\"}, {\"basis\": \"ACTD Framework, NFPA 3000 (PS) S19\", \"action\": \"Provide specialized training for all personnel on \'Take Action\' strategies within the ACTD framework, including techniques for securing a location and defensive actions as a last resort, avoiding \'Run/Hide/Fight\' language.\", \"priority\": \"30 Days\"}, {\"basis\": \"ACTD Framework, NFPA 3000 (PS) S19\", \"action\": \"Conduct scenario-based drills for active threat response in the multi-tenant environment, involving Site Lead (functions as Incident Commander per NIMS), Floor / Area Coordinators, and the External Coordinator / Responder Liaison.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s10_medical\", \"title\": \"Medical Emergency & Casualty Care\", \"content\": \"Medical emergencies at TEST 1, including those stemming from traumatic incidents, require a rapid and coordinated response to mitigate harm to the 240 occupants. The First Aid Coordinator, supported by designated Floor / Area Coordinators and other trained personnel, will serve as the initial medical response team. All personnel, especially those with first aid responsibilities, must receive regular training in basic first aid, CPR, and the use of Automated External Defibrillators (AEDs), ensuring readiness to address common medical emergencies as well as severe trauma.\\n\\nDesignated AED locations must be clearly marked and accessible on multiple floors throughout the 24-story building to ensure rapid deployment. Given the facility\'s size and occupancy, strategic placement of AEDs and comprehensive training on their use are critical. Furthermore, a robust bleeding control program, incorporating the STOP THE BLEED protocol, is essential. Bleeding control kits should be strategically placed alongside AEDs, and staff trained in their application. Triage procedures, aligned with incident severity, must be established to prioritize care for multiple casualties, ensuring the most severely injured receive immediate attention.\\n\\nCoordination with external Emergency Medical Services (EMS) is managed by the Emergency Caller (911) and the External Coordinator / Responder Liaison. Clear pathways for EMS access to all 24 floors must be pre-identified, especially in a multi-tenant building. Following any medical emergency, a review of the response, led by the First Aid Coordinator, should be conducted to identify areas for improvement in procedures, training, and equipment. This continuous improvement cycle is vital for maintaining a high level of medical preparedness.\", \"recommendations\": [{\"basis\": \"AHA/ILCOR 2020 Guidelines, OSHA 3185\", \"action\": \"Establish and clearly mark at least one AED per every two floors (12 total) at TEST 1, with easily accessible locations visible to all 240 occupants.\", \"priority\": \"Immediate\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Rescue & Medical Duties), AHA/ILCOR 2020 Guidelines, OSHA 3185\", \"action\": \"Train the First Aid Coordinator, all Floor / Area Coordinators, and at least 25% of the total staff in CPR, AED use, and STOP THE BLEED protocols.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38 (Rescue & Medical Duties)\", \"action\": \"Develop and implement a mass casualty triage protocol for TEST 1, specifically addressing procedures for multiple casualties across various floors, and incorporate it into emergency drills.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s11_reunification\", \"title\": \"Family Reunification & Accountability\", \"content\": \"Post-incident family reunification and occupant accountability are critical components of TEST 1\'s emergency plan, particularly given its 24-floor, multi-tenant structure and maximum occupancy of 240. An off-site reunification center must be designated, away from the immediate incident area, to provide a safe and controlled environment for families to reconnect. This location should be communicated to occupants and their families through pre-established emergency contact protocols. The Accountability Coordinator, in conjunction with Floor / Area Coordinators and the Site Lead (functions as Incident Commander per NIMS), is responsible for tracking all personnel and visitors during and after an incident.\\n\\nAccountability procedures for TEST 1 must utilize multiple methods to ensure accurate reconciliation of all 240 occupants across 24 floors. This includes primary roll calls at designated assembly points, cross-referencing with daily sign-in sheets, and leveraging emergency contact lists. For visitors, a clear protocol for release to verified family members or guardians must be established, potentially requiring photo identification and cross-referencing with visitor logs. This process ensures that individuals are released only to authorized persons and helps prevent exploitation during a crisis.\\n\\nFamily notification processes should outline clear communication channels and pre-approved messaging to inform next-of-kin about the incident and the reunification site. This involves the Emergency Caller (911) and External Coordinator / Responder Liaison working with external agencies. The Site Lead (functions as Incident Commander per NIMS) maintains overall command, ensuring that reunification and accountability efforts are integrated with broader incident management. Regular drills incorporating these reunification and accountability procedures are vital to test their effectiveness and refine the process for TEST 1.\", \"recommendations\": [{\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Designate and formalize a primary and secondary off-site family reunification center, and establish clear transportation plans from TEST 1\'s 24-floor facility.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Develop and implement a multi-tiered accountability system for all 240 occupants and visitors, utilizing electronic check-in/out systems, physical rosters, and Floor / Area Coordinator verification.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Family Reunification)\", \"action\": \"Establish formal family notification protocols, including pre-scripted messages and designated communication personnel, for use during and after an incident.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s12_media\", \"title\": \"Media & Public Information Management\", \"content\": \"Effective media and public information management are critical for TEST 1, a government facility, to maintain public trust and control narrative during and after an emergency. A single, designated spokesperson must be identified, ideally the Site Lead (functions as Incident Commander per NIMS) or a trained Public Information Officer (PIO) if available, to ensure all external communications are consistent, accurate, and authorized. This individual serves as the primary point of contact for all media inquiries, channeling information in a controlled manner.\\n\\nApproved messaging protocols must be pre-developed for various incident types relevant to TEST 1, including active threats, medical emergencies, and evacuations. These pre-scripted statements should be reviewed and approved by relevant stakeholders, ensuring they are compliant with organizational policies and sensitive to the nature of a government facility. All personnel, especially the External Coordinator / Responder Liaison, must be trained to direct media inquiries to the designated spokesperson and refrain from unauthorized comments, preventing the spread of misinformation or conflicting statements.\\n\\nSocial media guidelines must be established for TEST 1 personnel, emphasizing responsible use and the prohibition of posting sensitive information, speculation, or unauthorized content related to an incident. A designated social media monitoring and response team, reporting to the Site Lead (functions as Incident Commander per NIMS), should be in place to track public sentiment, correct misinformation, and disseminate official updates. This integrated approach ensures that information shared with the public, across all platforms, is managed strategically and in accordance with established crisis communication principles, as outlined by FEMA NIMS/ICS and NFPA 1600 (Crisis Communications).\", \"recommendations\": [{\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Crisis Communications)\", \"action\": \"Designate and formally train a primary and secondary spokesperson for TEST 1, ensuring they are proficient in crisis communication and media engagement.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Crisis Communications)\", \"action\": \"Develop and approve a library of pre-scripted messages for various emergency scenarios relevant to a 24-floor government facility, to ensure consistent and timely public information dissemination.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS, NFPA 1600 (Crisis Communications)\", \"action\": \"Establish comprehensive social media guidelines for all TEST 1 personnel and implement a protocol for official social media monitoring and response during an incident.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s13_training\", \"title\": \"Training, Drills & Exercise Program\", \"content\": \"A robust training, drill, and exercise program is fundamental for the TEST 1 facility to ensure that all personnel are proficient in emergency response procedures and understand their roles, especially given its multi-tenant, 24-floor government facility context. Regular training ensures that staff are familiar with the Emergency Action Plan (EAP) and can effectively respond to various threat scenarios, promoting a safer environment for all occupants. This program addresses the requirements for maintaining a prepared workforce capable of coordinated action.\\n\\nThe training regimen for TEST 1 will include a combination of foundational instruction, ongoing micro-drills, and comprehensive extended exercises. Initial training for all new hires and annual refresher training for existing staff will cover EAP components, communication protocols, and specific emergency roles. Micro-drills, such as simulated evacuation pathway reviews or communication system tests, will be conducted frequently to reinforce immediate action steps. Extended drills, conducted at least annually, will encompass various scenarios like shelter-in-place, evacuation, or medical emergencies, simulating realistic conditions to test procedural efficacy and inter-team coordination.\\n\\nExercise types for TEST 1 will range from tabletop exercises to functional and full-scale drills. Tabletop exercises will engage the Site Lead (functions as Incident Commander per NIMS) and key team members in discussion-based scenarios to validate plans and decision-making processes. Functional exercises will simulate specific EAP elements, such as a partial evacuation or a communications failure. Full-scale exercises, involving external emergency services and all facility personnel, will test the entire EAP under operational conditions, providing invaluable real-world experience. Each exercise will be followed by a structured after-action review (AAR) to identify strengths, weaknesses, and areas for improvement, culminating in actionable recommendations for plan refinement.\\n\\nThe overarching goal of TEST 1\'s training program is to cultivate a culture of preparedness, ensuring that all 240 occupants and staff can respond effectively and safely during an emergency. This includes tailored training for Floor / Area Coordinators to manage their zones across the 24 floors and for the Emergency Caller (911) and External Coordinator / Responder Liaison to ensure seamless communication with external agencies. Competency in these roles is critical for the swift and organized execution of emergency procedures in a government facility setting.\", \"recommendations\": [{\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38\", \"action\": \"Develop a comprehensive training curriculum for all TEST 1 staff, including initial onboarding training and annual refreshers covering the full scope of the Emergency Action Plan.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14\", \"action\": \"Implement a schedule for ongoing micro-drills (e.g., monthly) focusing on specific emergency procedures, and conduct at least one extended functional or full-scale exercise annually for TEST 1.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38\", \"action\": \"Establish a formal after-action review (AAR) process for all drills and exercises, ensuring that findings are documented, corrective actions are assigned, and the EAP is updated accordingly for TEST 1.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 3000 (PS) S10-14, OSHA 29 CFR 1910.38\", \"action\": \"Provide specialized training for all ICS roles identified for TEST 1, including the Site Lead (functions as Incident Commander per NIMS), Floor / Area Coordinators, and emergency communication roles.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s14_continuity\", \"title\": \"Business Continuity & Recovery\", \"content\": \"For the TEST 1 government facility, ensuring business continuity and a swift recovery following any disruptive event is paramount to maintaining essential services and public trust. A comprehensive Business Continuity Plan (BCP) must be developed to identify critical functions, establish recovery objectives, and outline strategies for restoring operations. This plan acknowledges the potential for significant impact from various emergencies and aims to minimize downtime and financial losses within the 2,400 sq. ft., 24-floor multi-tenant environment.\\n\\nThe BCP for TEST 1 will detail the restoration of critical functions, prioritizing services essential to the government\'s mission. This involves a thorough Business Impact Analysis (BIA) to determine Recovery Time Objectives (RTOs) and Recovery Point Objectives (RPOs) for each critical system and process. Strategies for alternate site operations will be explored, including agreements with nearby government facilities or dedicated off-site locations that can accommodate key personnel and equipment, considering the 240 maximum occupancy of TEST 1.\\n\\nData and records recovery is a central component of TEST 1\'s BCP. Secure, redundant backup solutions for all critical electronic data, coupled with strategies for accessing and restoring physical records, will be implemented. This includes outlining procedures for data synchronization and verification to ensure integrity and availability. Furthermore, the plan will address vendor and supplier continuity, establishing clear communication protocols and contingency plans for essential services and supplies. This involves pre-identifying alternative vendors and establishing agreements to ensure uninterrupted access to necessary resources.\\n\\nRecovery priorities for TEST 1 will focus on life safety, property protection, environmental stability, and then rapid restoration of mission-critical government services. The recovery phase will involve clear decision-making processes, led by the Site Lead (functions as Incident Commander per NIMS) and the External Coordinator / Responder Liaison, to coordinate with external agencies and manage resource allocation effectively. The BCP will provide a structured framework for returning TEST 1 to normal operations, leveraging robust emergency management principles to safeguard assets and ensure ongoing public service.\", \"recommendations\": [{\"basis\": \"NFPA 1600\", \"action\": \"Conduct a comprehensive Business Impact Analysis (BIA) for TEST 1 to identify critical government functions, establish Recovery Time Objectives (RTOs) and Recovery Point Objectives (RPOs), and prioritize recovery efforts.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Develop and document strategies for alternate site operations for TEST 1, including identification of potential temporary locations or agreements for shared resources within the multi-tenant building or with other government entities.\", \"priority\": \"90 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Implement robust data backup and recovery procedures for TEST 1\'s critical systems and records, ensuring off-site storage and regular testing of restoration capabilities.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Establish a vendor and supplier continuity program for TEST 1, including contingency plans for critical services, alternative supplier identification, and regular communication with key partners.\", \"priority\": \"90 Days\"}]}, {\"id\": \"s15_special_populations\", \"title\": \"Special Populations & Accessibility\", \"content\": \"Given TEST 1\'s status as a government facility and its 24-floor, multi-tenant environment with a maximum occupancy of 240, it is imperative to establish clear procedures for assisting special populations and ensuring accessibility during emergencies. This includes individuals with disabilities, non-English speakers, visitors, and contractors. Adherence to accessibility standards is not only a regulatory requirement but also a fundamental aspect of inclusive emergency preparedness, ensuring the safety and well-being of every person within the facility.\\n\\nProcedures for individuals with disabilities at TEST 1 must comply with ADA Title III and Section 504 of the Rehabilitation Act. This involves pre-identifying individuals who may require assistance, establishing a confidential registry, and developing personalized emergency plans. Evacuation procedures will prioritize accessible egress routes, the use of evacuation chairs where appropriate for vertical movement across 24 floors, and designated Areas of Refuge. Trained personnel, including Floor / Area Coordinators, will be assigned to provide assistance, ensuring that individuals are not left behind during an emergency. Communication methods will also be adapted to include visual, auditory, and tactile formats as needed.\\n\\nFor non-English speakers, TEST 1 will implement strategies to overcome language barriers during emergencies. This includes developing multilingual emergency signage, pre-recorded announcements in common languages spoken in the area, and identifying staff members who are proficient in other languages to assist with communication. Interpretation services or communication aids will be available to convey critical information effectively to ensure everyone understands emergency instructions and can respond appropriately.\\n\\nVisitors and contractors within TEST 1 also constitute a special population requiring specific protocols. Upon entry, all visitors and contractors will receive clear instructions regarding emergency procedures, evacuation routes, and points of assembly. This may include providing visitor-specific emergency guides, a brief orientation, or utilizing digital information boards. The External Coordinator / Responder Liaison will ensure that emergency services are aware of the presence of visitors and contractors during an incident, and accountability procedures will be in place to track all individuals present in the 2,400 sq. ft. facility during operating hours.\", \"recommendations\": [{\"basis\": \"ADA Title III, Section 504 (Rehabilitation Act), OSHA 29 CFR 1910.38\", \"action\": \"Develop and implement a pre-identification program for individuals with disabilities or special needs at TEST 1, including a confidential registry and personalized emergency plans, in compliance with ADA Title III and Section 504.\", \"priority\": \"90 Days\"}, {\"basis\": \"ADA Title III, Section 504 (Rehabilitation Act)\", \"action\": \"Ensure that TEST 1\'s emergency egress paths, Areas of Refuge, and evacuation equipment (e.g., evacuation chairs) are readily accessible and maintained for individuals with disabilities across all 24 floors, as required by ADA Title III.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Implement multilingual emergency signage and communication protocols at TEST 1 to effectively convey emergency instructions to non-English speaking occupants, including staff identification for language assistance.\", \"priority\": \"90 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38\", \"action\": \"Establish clear procedures for informing visitors and contractors of TEST 1\'s emergency protocols upon entry, including providing concise emergency instructions and ensuring accountability during incidents.\", \"priority\": \"60 Days\"}]}, {\"id\": \"s16_maintenance\", \"title\": \"Plan Maintenance & Review Schedule\", \"content\": \"Effective emergency preparedness for TEST 1, a 24-floor government facility with a maximum occupancy of 240, hinges on a meticulously maintained and regularly reviewed Emergency Action Plan (EAP). The dynamic nature of personnel, facility layout, and potential threats necessitates a structured approach to plan maintenance to ensure its continued relevance, accuracy, and effectiveness. A living document, the EAP for TEST 1 must be adaptable to operational changes and lessons learned.\\n\\nThe EAP for TEST 1 will undergo a comprehensive review at least annually, with the effective date being July 27, 2026, and a review date of July 27, 2027. This annual review will involve key stakeholders, including the Site Lead (functions as Incident Commander per NIMS), ICS roles, facility management, and tenant representatives from the multi-tenant building. The review process will scrutinize all EAP sections, including evacuation routes, communication protocols, role assignments, and resource inventories, ensuring alignment with current facility conditions, staffing, and regulatory requirements.\\n\\nTrigger events will prompt immediate revisions to the EAP, independent of the annual review cycle. Such events for TEST 1 include any actual emergency incidents, significant facility alterations (e.g., renovations, structural changes affecting egress, or changes to critical infrastructure), substantial changes in personnel (especially those holding ICS roles), or updates to relevant federal, state, or local regulations. These revisions ensure that the EAP remains current and reflective of the operational environment, preventing the plan from becoming outdated or ineffective.\\n\\nRobust version control and a clear distribution list are critical components of TEST 1\'s plan maintenance. Each revision of the EAP will be assigned a unique version number and date, and all changes will be formally documented. The distribution list will ensure that all relevant personnel, including Floor / Area Coordinators, emergency services, and key stakeholders, receive the most current version of the plan. Electronic copies will be maintained in a secure, accessible location, and hard copies will be strategically placed throughout the 2,400 sq. ft. facility to ensure immediate access during an emergency.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38, NFPA 1600\", \"action\": \"Establish a formal annual review schedule for TEST 1\'s EAP, involving key stakeholders, and set the review date to July 27, 2027, ensuring the plan remains current and accurate.\", \"priority\": \"60 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38, NFPA 1600\", \"action\": \"Define specific trigger events (e.g., incidents, facility changes, personnel changes, regulatory updates) that mandate immediate revisions to TEST 1\'s EAP, outside of the annual review cycle.\", \"priority\": \"60 Days\"}, {\"basis\": \"NFPA 1600\", \"action\": \"Implement a rigorous version control system for TEST 1\'s EAP, assigning unique identifiers and documenting all changes, to ensure that only the most current version is in use.\", \"priority\": \"30 Days\"}, {\"basis\": \"OSHA 29 CFR 1910.38, NFPA 1600\", \"action\": \"Maintain an updated distribution list for TEST 1\'s EAP, ensuring that all relevant personnel and external agencies receive timely access to the current plan, both electronically and in designated hard copy locations.\", \"priority\": \"30 Days\"}]}, {\"id\": \"s17_appendices\", \"title\": \"Appendices & Supporting Documents\", \"content\": \"The appendices and supporting documents are integral to the TEST 1 Emergency Action Plan (EAP), providing critical reference materials that enhance its practicality and effectiveness. For a 24-floor government facility with a maximum occupancy of 240, having readily available contact information, detailed floor plans, and resource lists is essential for rapid decision-making and coordinated response during an emergency. These documents consolidate vital information that may be too detailed for the main body of the EAP but is crucial for operational execution.\\n\\nCentral to the appendices is a comprehensive contact directory. This directory for TEST 1 will include up-to-date contact information for emergency services (police, fire, EMS), key facility staff (including the Site Lead (functions as Incident Commander per NIMS) and other ICS role holders), and essential vendors (e.g., HVAC, security systems, utilities). Having this information readily accessible ensures that appropriate personnel and external resources can be contacted swiftly during any incident, streamlining the communication process and facilitating timely assistance.\\n\\nDetailed floor plan references are indispensable for navigating the 2,400 sq. ft., 24-floor multi-tenant building during an emergency. The appendices will include clear, legible floor plans for each level of TEST 1, highlighting evacuation routes, emergency exits, fire extinguishers, first aid stations, utility shut-off points, and Areas of Refuge. These plans are vital for Floor / Area Coordinators and emergency responders to efficiently guide evacuations, locate individuals, and manage resources within the complex layout.\\n\\nFurther supporting documents will include a comprehensive resource list detailing available equipment (e.g., AEDs, first aid kits, emergency lighting), their locations, and responsible parties. Any mutual aid agreements with neighboring multi-tenant facilities or local government agencies will also be appended, outlining protocols for shared resources and coordinated response efforts. Finally, a list of supporting regulatory references will be included to ensure ongoing compliance and provide a basis for plan review and updates, reinforcing TEST 1\'s commitment to comprehensive emergency preparedness.\", \"recommendations\": [{\"basis\": \"OSHA 29 CFR 1910.38 (Named Contact Person), FEMA NIMS/ICS\", \"action\": \"Compile and regularly update a comprehensive contact directory for TEST 1, including emergency services, all key facility staff (especially the Named Contact Person per OSHA 1910.38), and critical vendors.\", \"priority\": \"30 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Develop and include detailed floor plans for each of TEST 1\'s 24 floors in the appendices, clearly marking evacuation routes, emergency exits, utility shut-offs, and critical safety equipment.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Create a comprehensive resource list for TEST 1, itemizing all emergency equipment, their locations, and designated personnel responsible for their use and maintenance.\", \"priority\": \"60 Days\"}, {\"basis\": \"FEMA NIMS/ICS\", \"action\": \"Document and include any formal mutual aid agreements or inter-agency cooperation protocols relevant to TEST 1\'s emergency response in the appendices.\", \"priority\": \"90 Days\"}]}], \"planTitle\": \"Emergency Action Plan -- TEST 1\", \"reviewDate\": \"July 27, 2027\", \"facilitySize\": \"large\", \"assignedRoles\": [\"Site Lead (functions as Incident Commander per NIMS)\", \"Secondary Lead / Backup\", \"Emergency Caller (911)\", \"Evacuation Coordinator\", \"Accountability Coordinator\", \"External Coordinator / Responder Liaison\", \"First Aid Coordinator\", \"Floor / Area Coordinators (one per floor/zone)\"], \"effectiveDate\": \"July 27, 2026\", \"executiveSummary\": \"This Emergency Action Plan has been developed for TEST 1 following a comprehensive workplace safety assessment conducted on July 27, 2026. The plan is aligned with FEMA NIMS/ICS, NFPA 3000 (PS), OSHA 29 CFR 1910.38, OSHA 29 CFR 1910.165, NFPA 1600, and the ACTD Framework (aligned with CISA active threat preparedness principles).\", \"standardsAlignment\": [\"FEMA NIMS\", \"FEMA ICS\", \"NFPA 3000 (PS)\", \"OSHA 29 CFR 1910.38\", \"OSHA 29 CFR 1910.165\", \"NFPA 1600\", \"ACTD Framework (aligned with CISA active threat preparedness principles)\"]}','2026-07-27 11:01:18',NULL,NULL,NULL);
