  `generationMode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userPrompt` longtext COLLATE utf8mb4_unicode_ci,
  `content` json DEFAULT NULL,
  `regulatoryTags` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
