INSERT INTO `drill_templates` VALUES (1,NULL,NULL,'extended',NULL,NULL,NULL,NULL,'2026-05-27 14:51:23','2026-05-27 14:51:23',1,1,'Unauthorized Access & Escalation at NATHANAEL BERNARDO STA. CATALINA',20,'Transportation','United States','system',NULL,'{\"actd\": {\"assess\": {\"whatToNotice\": [\"Unverified individual bypassing security protocols (sign-in kiosk).\", \"Behavioral cues: agitation, lack of eye contact, rapid movement towards a restricted zone.\", \"Direct non-compliance to verbal engagement and aggressive attempt to breach secured access.\", \"Awareness of current staffing levels (evening operations) and location of key personnel.\"], \"signalsThatMatter\": [\"The shift from passive non-compliance to active attempted forced entry and aggressive non-response signals clear hostile intent or significant distress requiring immediate intervention.\", \"The individual\'s forward progression deeper into controlled space constitutes a direct threat to the safety and security of occupants and operations.\"]}, \"commit\": {\"hesitationRisks\": [\"Delay in alerting security or activating lockdown procedures allows the individual to gain further access, potentially leading to a direct confrontation with staff or access to sensitive areas.\", \"Assuming the individual is simply lost or confused, despite aggressive actions, can lead to under-response and increased personal exposure.\", \"Waiting for a more overt \'weapon\' indicator to act, when behavioral cues already signal clear threat.\"], \"decisionRequired\": \"Decide on an immediate, coordinated action to address the unauthorized individual\'s attempted forced entry and escalating aggressive behavior, balancing personal safety with facility security.\"}, \"debrief\": {\"whatToImprove\": [\"Refine initial recognition of escalating behavioral cues and threshold for intervention.\", \"Strengthen inter-departmental and multi-tenant communication protocols for rapid threat dissemination.\", \"Evaluate effectiveness of physical access control points and staff training on their operation.\", \"Review decision-making processes under high stress for early commitment to protective actions.\", \"Assess resource allocation and response times for internal security and external law enforcement coordination.\"], \"whatToDocument\": [\"Timeline of observed behaviors, actions, and communications.\", \"Specific verbal challenges made and individual\'s reactions.\", \"Details of security notifications (time, recipient, information conveyed).\", \"Effectiveness of access control points and staff training on challenging unauthorized individuals.\", \"Identification of any physical or procedural vulnerabilities exploited by the individual.\"]}, \"takeAction\": {\"adaptabilityNote\": \"Actions must adapt based on the individual\'s reaction to verbal commands, their rate of progression, and the proximity of other staff or critical assets. Preparedness for a potential breach is paramount.\", \"availableActions\": [\"Initiate a building-wide alert for unauthorized person and potential lockdown (if protocol exists).\", \"Immediately notify building security and provide a detailed description and last known location.\", \"Verbally challenge the individual with firm, clear commands to halt, while maintaining a safe distance.\", \"Direct nearby staff to shelter-in-place or evacuate away from the threat\'s path.\", \"Utilize available physical barriers or positioning to create distance and reduce direct exposure.\"]}}, \"title\": \"Unauthorized Access & Escalation at NATHANAEL BERNARDO STA. CATALINA\", \"injects\": [{\"event\": \"The individual, ignoring Alex\'s verbal challenge, forces open the locked employee access door, shouts, \'Where\'s the manager who lost my shipment?!\', and strides into the main open-plan office space, moving towards a cluster of desks where two employees are still working.\", \"timeMarker\": \"00:02\", \"injectNumber\": 1, \"facilitatorNote\": \"Observe if Alex prioritizes personal safety, activates the alert system, and provides clear, concise information to Maria and any arriving security personnel. Note any hesitation or attempts at direct physical intervention.\", \"expectedDecision\": \"Reception Staff (Alex) immediately activates internal emergency alert, contacts Operations Supervisor (Maria), and initiates a localized shelter-in-place for visible staff, while maintaining distance.\"}, {\"event\": \"The individual reaches the occupied desks, slams their hand on one, and confronts an employee, demanding answers aggressively. Meanwhile, Alex\'s alert has reached Maria on the 2nd floor. Building security, responding to the alert, calls Alex for an update while en route.\", \"timeMarker\": \"00:07\", \"injectNumber\": 2, \"facilitatorNote\": \"Assess Maria\'s ability to escalate the protective actions for all staff and coordinate with external responders. Observe Building Security\'s communication with Alex and their decision to involve law enforcement. Note if Maria\'s instructions are clear and timely for staff on the second floor.\", \"expectedDecision\": \"Operations Supervisor (Maria) initiates full office lockdown/shelter-in-place and coordinates with Building Security on tactical approach. Building Security confirms threat location and intent with Alex, then updates law enforcement on active hostile individual.\"}, {\"event\": \"The individual, agitated by the noise of the building-wide alert, picks up a stapler from a desk and gestures with it while continuing to yell at the employee. Building Security is now at the entrance to the NATHANAEL BERNARDO STA. CATALINA office, approximately 50 feet from the incident.\", \"timeMarker\": \"00:12\", \"injectNumber\": 3, \"facilitatorNote\": \"Evaluate Building Security\'s judgment in attempting de-escalation vs. immediate intervention, given the weaponized object and law enforcement ETA. Assess Maria\'s ongoing coordination for personnel safety and her ability to maintain a clear communication channel with Security.\", \"expectedDecision\": \"Building Security attempts verbal de-escalation from a safe distance, establishes a containment perimeter at the office entrance, and prepares for tactical intervention as local law enforcement ETA is given as 5-7 minutes. Maria ensures all other staff are accounted for in secure locations.\"}], \"scenario\": \"It is 6:15 PM during evening operations at the NATHANAEL BERNARDO STA. CATALINA transportation office. A staff member, Alex, is at the main reception desk on the first floor of the multi-tenant building. An agitated man enters through a public entrance, bypassing the visitor sign-in kiosk and deliberately avoiding eye contact. He walks directly past Alex, heading towards the employee-only access point that leads to the main office floor. Alex attempts to verbally engage, \'Can I help you, sir?\' The man ignores Alex, quickens his pace, and forcefully attempts to pull open the locked employee door, glaring back when verbally challenged again.\", \"drillType\": \"extended\", \"objective\": \"To train key personnel in a transportation office environment to rapidly recognize escalating unauthorized access, commit to immediate control and coordination actions, and adapt response as the threat progresses.\", \"teamRoles\": [{\"role\": \"Reception Staff (Alex)\", \"primaryAction\": \"Alert internal security and building management; initiate immediate lockdown/shelter for nearby personnel.\", \"communicationTrigger\": \"Individual ignores verbal warning and attempts forced entry.\"}, {\"role\": \"Operations Supervisor (Maria)\", \"primaryAction\": \"Direct staff to designated safe zones or evacuation routes; coordinate with security on threat location and status.\", \"communicationTrigger\": \"Notification from Reception Staff or direct observation of threat.\"}, {\"role\": \"Building Security\", \"primaryAction\": \"Respond to threat location; establish visual and verbal control; prepare for potential physical intervention; notify local law enforcement.\", \"communicationTrigger\": \"Alert from tenant (Reception Staff or Operations Supervisor) regarding unauthorized access/escalation.\"}, {\"role\": \"Building Management\", \"primaryAction\": \"Activate building-wide emergency protocols (if multi-tenant system); ensure external law enforcement coordination; communicate with all tenants.\", \"communicationTrigger\": \"Notification from NATHANAEL BERNARDO STA. CATALINA Operations Supervisor or Building Security.\"}], \"exerciseType\": \"tabletop\", \"scenarioType\": \"Unauthorized Access\", \"behavioralCues\": [\"Agitated demeanor\", \"Avoidance of eye contact\", \"Bypassing established visitor protocols\", \"Increased pace toward restricted areas\", \"Ignoring verbal commands\", \"Attempting forced entry on a secured door\", \"Aggressive body language\"], \"guidedResponse\": {\"commonHumanErrors\": [\"Underestimating the threat, assuming benign intent, waiting for a definitive weapon display, or delaying alert activation due to fear of \'overreacting\' or causing disruption.\"], \"decisionMakingLens\": [\"The focus shifts from customer service to threat mitigation: preserving life, controlling access, and activating the coordinated response chain are paramount, overriding any social hesitation.\"], \"howAnExpertAssesses\": [\"The expert immediately identifies multiple boundary violations (bypassing sign-in, attempting forced entry) and escalating behavioral indicators (agitation, non-compliance, aggression), confirming an active threat, not just a lost visitor.\"], \"performanceStandard\": \"Rapidly recognize escalating threat, immediately activate the highest level of appropriate alert, and execute coordinated protective actions for staff and facility integrity.\", \"actionConsiderations\": [\"Evaluate immediate personal exposure, proximity to other staff, available escape routes, and the fastest means to initiate a facility-wide alert and summon specialized assistance (security, law enforcement).\"]}, \"durationMinutes\": 20, \"expectedOutcome\": {\"correctDecision\": \"Rapid activation of the response chain and immediate lockdown efforts create an active deterrent and facilitate a structured security response, potentially leading to containment or redirection of the individual before deeper access is gained.\", \"incorrectDecision\": \"Hesitation or delayed notification allows the individual to breach secured areas, increasing the risk of direct confrontation with staff and escalating the threat to human safety throughout the facility without coordinated intervention.\"}, \"decisionPressure\": \"Ambiguity of intent, time urgency, potential for physical confrontation, multi-tenant coordination.\", \"escalationMoment\": \"The individual ignores a verbal challenge from staff, quickens their pace, and attempts to force open a locked employee access door, displaying aggressive body language.\", \"facilitatorSetup\": {\"roomSetup\": \"Large conference room with tables arranged to represent the 1st and 2nd floors of the NATHANAEL BERNARDO STA. CATALINA office. Printouts of floor plans for each participant. Designated areas for \'security desk\' and \'command center\'.\", \"materialsNeeded\": [\"Printed floor plans (1st and 2nd floor) for each participant.\", \"Role cards for Alex, Maria, Security, Building Management.\", \"Pens, notepads, flip charts for recording decisions and observations.\", \"Timer to manage injects.\", \"Optional: Small tokens or markers to represent individuals on floor plans.\"], \"preExerciseBriefing\": \"Welcome to the NATHANAEL BERNARDO STA. CATALINA Extended Scenario. This exercise is designed to test real-time decision-making, communication, and coordination under stress, focusing on unauthorized access and escalating human behavior. Remember, ACTD is dynamic, not linear. There are no \'surprise\' elements here; only opportunities to refine your response. Focus on Recognition, Control, Coordination, and Containment. This is NOT a pass/fail assessment.\"}, \"participantRoles\": [{\"role\": \"Reception Staff (Alex)\", \"briefing\": \"You are the evening receptionist. Your primary duties include visitor management, basic administrative tasks, and being the first point of contact. You are currently alone at the reception desk on the 1st floor.\", \"keyDecision\": \"Initial recognition of threat, activation of alert, and communication of critical information to management and security.\"}, {\"role\": \"Operations Supervisor (Maria)\", \"briefing\": \"You oversee evening operations and are currently in your office on the 2nd floor. You have direct communication lines to Alex and Building Security, and the authority to implement facility-wide protective actions.\", \"keyDecision\": \"Decision to implement full lockdown/evacuation, coordination of personnel safety, and strategic communication with Building Security and Building Management.\"}, {\"role\": \"Building Security\", \"briefing\": \"You are the contracted security officer responsible for the multi-tenant building\'s common areas. You are currently on patrol on the ground floor. You are equipped with a radio and direct line to building management and local emergency services.\", \"keyDecision\": \"Decision to respond, intercept, establish control, and coordinate with law enforcement and internal facility personnel.\"}, {\"role\": \"Building Management Representative\", \"briefing\": \"You represent the overarching building management. You are responsible for the safety of all tenants, activating building-wide alerts, and formal liaison with external emergency services. You are off-site but reachable by phone.\", \"keyDecision\": \"Decision to activate building-wide alerts, authorize major protective actions affecting all tenants, and coordinate with law enforcement\'s on-scene commander.\"}], \"roleBasedActions\": [{\"role\": \"Reception Staff (Alex)\", \"action\": \"Initiate building lockdown procedures and immediate internal alert to management and security while maintaining visual distance.\", \"rationale\": \"Prioritizes personal safety and activates the organizational response chain without direct confrontation, allowing security to intercept.\"}, {\"role\": \"Operations Supervisor (Maria)\", \"action\": \"Coordinate evacuation of staff from immediate area of threat and ensure rapid communication to all floors and other tenants.\", \"rationale\": \"Reduces exposure for personnel in the path of progression and disseminates critical threat information across the facility and building.\"}, {\"role\": \"Building Security (Contracted)\", \"action\": \"Move to intercept the unauthorized individual at the point of entry/escalation, establish verbal control, and coordinate with local law enforcement.\", \"rationale\": \"Addresses the boundary violation and escalating behavior with direct intervention, aiming to contain the threat and involve external authorities.\"}], \"scenarioTimeline\": [{\"event\": \"Agitated individual bypasses reception and moves toward secured employee door.\", \"timeMarker\": \"00:00\", \"expectedAction\": \"Reception staff attempts verbal engagement.\"}], \"criticalDecisions\": [\"Reception staff\'s immediate action upon first verbal challenge being ignored and door forced.\", \"Operations Supervisor\'s decision to initiate full facility lockdown and personnel evacuation from vulnerable areas.\", \"Building Security\'s choice between direct intervention, containment, and immediate law enforcement handover given the evolving threat (weaponized object).\", \"Coordination of clear, consistent communication across all roles and to other tenants within the multi-tenant building.\"], \"communicationsFlow\": {\"publicCommunication\": \"None initiated unless directed by law enforcement after incident resolution.\", \"externalNotification\": \"Building Security to local law enforcement (911); Building Management to all other building tenants (email/text alert system).\", \"internalNotification\": \"Reception to Operations Supervisor and Building Security via direct line/radio; Operations Supervisor to all NATHANAEL BERNARDO STA. CATALINA staff via internal messaging/PA system.\"}, \"afterActionTemplate\": {\"gapsPrompt\": \"Pinpoint specific points where hesitation, unclear communication, or protocol misalignment introduced additional risk or delayed effective response.\", \"strengthsPrompt\": \"Identify three areas where communication, decision-making, or coordination were particularly effective during this exercise.\", \"followUpDeadline\": \"30 days\", \"improvementActions\": \"Propose three concrete, actionable steps to improve response capabilities for unauthorized access and escalating behavior incidents based on lessons learned.\"}, \"primaryThreatSignal\": \"Unauthorized access escalating to aggressive behavior and attempted forced entry.\", \"preIncidentIndicator\": \"An agitated individual bypasses the visitor sign-in kiosk and avoids eye contact with reception staff, moving directly towards an employee-only access point without authorization.\", \"communicationRequirement\": {\"sender\": \"Reception Staff\", \"message\": \"Unauthorized, aggressive individual attempting to force access into secured office space on 1st floor.\", \"trigger\": \"Individual ignores verbal challenge and attempts to force a locked door.\", \"recipient\": \"Operations Supervisor, Building Security, Building Management\"}}','[]'),(2,NULL,NULL,'micro',NULL,NULL,NULL,NULL,'2026-05-27 16:13:25','2026-05-27 16:13:25',1,1,'Unauthorized Access Escalation at Government Facility',2,'Government','United States','system',NULL,'{\"actd\": {\"assess\": {\"whatToNotice\": [\"Forced entry against access control measures.\", \"Bypass of primary control points (reception).\", \"Disregard for restricted area signage.\", \"Direct, purposeful movement deeper into the facility.\", \"Lack of response to environmental cues or potential staff presence.\"], \"signalsThatMatter\": [\"The transition from loitering to forced entry indicates hostile intent or extreme non-compliance.\", \"Movement into restricted areas confirms boundary violation and intent to evade.\", \"The absence of attempts to engage staff suggests a deliberate avoidance strategy.\"]}, \"commit\": {\"hesitationRisks\": [\"Allowing deeper penetration into controlled space.\", \"Increased exposure for self or others.\", \"Loss of critical time for a coordinated response.\", \"Incomplete or inaccurate information dissemination to responders.\"], \"decisionRequired\": \"Decide immediately whether to prioritize personal safety and early alert activation, or to attempt direct engagement/observation, accepting the associated risks of delayed coordinated response.\"}, \"debrief\": {\"whatToImprove\": [\"Speed of threat recognition.\", \"Efficiency of activating communication protocols.\", \"Ability to prioritize personal safety while initiating response.\", \"Understanding of designated shelter-in-place locations.\"], \"whatToDocument\": [\"Exact time of entry and observed behaviors.\", \"Direction of travel and specific areas accessed.\", \"Physical description of the individual.\", \"Your actions taken and coordination attempts.\"]}, \"takeAction\": {\"adaptabilityNote\": \"The optimal action adapts to the immediate threat proximity, available cover, and ability to activate the response chain without increasing personal exposure.\", \"availableActions\": [\"Activate emergency alert system and seek cover.\", \"Challenge the individual verbally from a safe distance.\", \"Maintain observation from concealment while preparing to report.\"]}}, \"title\": \"Unauthorized Access Escalation at Government Facility\", \"scenario\": \"It\'s 6:30 PM, past regular operating hours, at a two-story government office facility within a multi-tenant building. You are working late in your first-floor office. You notice an individual who had been standing suspiciously near the main public entrance for several minutes suddenly force the door open. The person bypasses the unattended reception desk and moves directly towards an internal staff-only corridor, ignoring clearly posted \'Authorized Personnel Only\' signage. They are not making eye contact with anyone and are moving with purpose deeper into the facility.\", \"drillType\": \"micro\", \"objective\": \"Train staff to recognize and initiate immediate, appropriate response to unauthorized access and escalating behavior in a government office facility environment.\", \"outcomeMap\": {\"Challenge audibly from a distance\": {\"tradeoff\": \"Gained a momentary attempt at direct control; introduced potential for immediate subject escalation and delayed formal response.\", \"riskLevel\": \"Moderate Risk Response\", \"consequence\": \"The individual pauses briefly, looks in your general direction, then accelerates their movement further down the corridor, now appearing more agitated. Your attempt to gain information caused a momentary hesitation, but also escalated their pace. Security notification is now delayed.\", \"likelyOutcome\": \"The individual continues their progression, potentially now hostile due to direct engagement. You are in closer proximity with an agitated individual and the security response is not yet active, increasing personal risk and the complexity of future intervention.\", \"whyThisMatters\": \"This decision introduces direct risk and can provoke a faster escalation without immediately engaging the full response chain.\", \"humanRealismNote\": \"The instinct to verbally challenge and assert control is strong, especially when an individual is clearly violating rules, but it can unexpectedly provoke escalation.\", \"coachingConnection\": \"While challenging might provide some information, it introduces direct personal exposure and a higher chance of escalating the subject\'s behavior. It also delays the critical step of activating the formal response, leaving you isolated.\"}, \"Maintain observation, do not alert yet\": {\"tradeoff\": \"Gained more information and maintained personal concealment; introduced significant delay in organizational response and allowed deeper penetration.\", \"riskLevel\": \"Introduces Additional Risk\", \"consequence\": \"The individual continues unhindered into a restricted operations area, now completely out of your line of sight. Valuable time for early intervention and coordinated response has been lost, and the scope of the unauthorized access is unknown. The response chain remains inactive.\", \"likelyOutcome\": \"The individual disappears into an unknown area of the facility. Without an active alert, security is unaware, and the scope of the threat expands rapidly. You are left with incomplete information and no coordinated backup, compromising overall safety and response capabilities.\", \"whyThisMatters\": \"This decision allows for uncontested progression, critically delaying coordinated response and increasing the potential for significant harm or compromise.\", \"humanRealismNote\": \"There\'s a natural desire to fully understand a situation before raising an alarm, especially in a quiet environment, which can lead to critical delays.\", \"coachingConnection\": \"This choice risks losing control and allowing the individual to gain significant ground into sensitive areas. While gathering information can be useful, the priority in an unauthorized access scenario is immediate notification and containment, as the threat is already evident.\"}, \"Activate internal alert and move to cover\": {\"tradeoff\": \"Gained immediate organizational response and personal safety; introduced a temporary loss of direct visibility.\", \"riskLevel\": \"Lowest Risk Response\", \"consequence\": \"Security dispatch confirms alert receipt and is directing patrol units. The individual continues moving deeper into the internal corridor, potentially bypassing other secure areas before arrival. Containment efforts are now underway, but a timing gap exists.\", \"likelyOutcome\": \"Responding units are en route and aware of the individual\'s direction of travel. The individual may encounter security assets further inside the facility, but the immediate threat to you is reduced. The situation remains dynamic with active containment efforts.\", \"whyThisMatters\": \"This decision initiates a structured organizational response, reducing individual risk and enabling coordinated threat management.\", \"humanRealismNote\": \"Prioritizing personal safety and activating alerts early can feel counter-intuitive to \'doing something\' directly, but it\'s a critical, low-exposure action.\", \"coachingConnection\": \"This choice activates the response chain efficiently, reducing your personal exposure and enhancing overall containment capability. The perceived loss of control is offset by rapid activation of resources.\"}}, \"scenarioType\": \"Unauthorized Access\", \"behavioralCues\": [\"Forced entry\", \"Bypassing reception\", \"Ignoring signage\", \"No eye contact\", \"Moving with purpose into restricted area\"], \"guidedResponse\": null, \"durationMinutes\": 2, \"expectedOutcome\": {\"correctDecision\": \"Rapid activation of the response chain allows for early interception attempts and reduces the individual\'s time for deeper penetration, enhancing the safety of personnel.\", \"incorrectDecision\": \"Delayed reporting allows the unauthorized individual to gain unchallenged access to sensitive areas, increasing potential harm and complicating the eventual response.\"}, \"responseOptions\": [\"Activate internal alert and move to cover\", \"Challenge audibly from a distance\", \"Maintain observation, do not alert yet\"], \"commonBreakdowns\": [], \"debriefQuestions\": [], \"decisionPressure\": \"Ambiguity regarding intent, need for rapid coordination, and personal safety while preventing deeper facility penetration.\", \"escalationMoment\": \"The individual forces the public entrance door open, bypasses the unattended reception desk, and moves directly towards an internal staff-only corridor, ignoring \'Authorized Personnel Only\' signage.\", \"expectedOutcomes\": [], \"roleBasedActions\": [{\"role\": \"Staff\", \"action\": \"Activate internal alert and seek immediate secure positioning.\", \"rationale\": \"Prioritize personal safety and initiate organizational response chain without direct confrontation.\"}, {\"role\": \"Responder / Security\", \"action\": \"Initiate immediate patrol dispatch and remote monitoring of the identified corridor.\", \"rationale\": \"Contain the threat\'s progression and prepare for physical interception.\"}, {\"role\": \"Admin / Supervisor\", \"action\": \"Notify emergency services and prepare for facility-wide lockdown protocols.\", \"rationale\": \"Ensure external support is mobilized and internal personnel are secured.\"}], \"primaryThreatSignal\": \"Unauthorized access with escalating behavioral indicators and forward progression.\", \"regulatoryAlignment\": [], \"microDebriefQuestion\": \"What specific actions by the individual confirmed this was an unauthorized access requiring immediate action, not just a lost visitor?\", \"preIncidentIndicator\": \"An individual has been standing suspiciously near the main public entrance of the government office for several minutes past operating hours, making repeated attempts to look inside without approaching the public access button.\", \"executionInstructions\": [], \"communicationRequirement\": {\"sender\": \"Staff\", \"message\": \"Unauthorized individual forced entry, proceeding into staff-only corridor.\", \"trigger\": \"Immediate observation of forced entry and boundary violation.\", \"recipient\": \"Facility Security / Emergency Services\"}, \"compressedGuidedResponse\": {\"bestNextMove\": \"The best next move is to trigger the emergency alert system and move to a secure location, simultaneously providing critical real-time updates to responding personnel.\", \"criticalDecision\": \"The critical decision is to immediately activate the response chain and secure your own position versus attempting direct intervention or delaying alert.\", \"mostLikelyMistake\": \"The most likely mistake is hesitation due to ambiguity or a desire to gather more information, allowing the individual to gain uncontested access deeper into restricted areas.\", \"howAnExpertReadsThis\": [\"An expert immediately identifies a critical boundary violation and escalating behavioral indicators demanding rapid response, prioritizing early notification and personal safety.\"]}}','[]'),(3,NULL,NULL,'micro',NULL,NULL,NULL,NULL,'2026-05-27 18:29:48','2026-05-27 18:29:48',1,1,'Unauthorized Access into Restricted Office Area',2,'Education','United States','system',NULL,'{\"actd\": {\"assess\": {\"whatToNotice\": [\"Individual bypassing established access points and ignoring normal entry procedures.\", \"Lack of identification or authorization indicators for after-hours access.\", \"Evasive behavior, such as avoiding eye contact and rapid, directed movement.\", \"Intent to enter restricted, secured spaces despite clear \'Staff Only\' signage.\"], \"signalsThatMatter\": [\"Persistent forward movement into non-public, sensitive areas.\", \"Non-compliance with expected entry protocols for visitors or staff.\", \"Attempting to open secured doors without valid credentials.\"]}, \"commit\": {\"hesitationRisks\": [\"Allowing the individual to gain deeper access and potentially encounter other staff or sensitive assets.\", \"Delaying the activation of the organizational response chain, leading to a slower, less coordinated intervention.\", \"Increasing personal exposure by attempting solo intervention without backup or strategic positioning.\"], \"decisionRequired\": \"Decide whether to engage directly, activate an immediate organizational alert, or prioritize cover while documenting, recognizing that delay increases risk.\"}, \"debrief\": {\"whatToImprove\": [\"Timeliness of threat recognition and interpretation of ambiguous cues.\", \"Efficiency and clarity of internal communication and alert activation processes.\", \"Personal positioning and movement relative to threat progression to ensure safety and maintain visibility.\"], \"whatToDocument\": [\"Exact time and specific location of initial observation and each key escalation point.\", \"Detailed description of the individual (clothing, distinguishing features, apparent demeanor).\", \"Observed behaviors, direction of movement, and any verbalizations or actions toward doors.\", \"Specific actions taken by the observer and the immediate outcomes or changes in the situation.\"]}, \"takeAction\": {\"adaptabilityNote\": \"Actions must adapt based on the individual\'s reaction (compliance, evasion, escalation) and the immediate availability of egress or shelter points.\", \"availableActions\": [\"Activating immediate emergency alert systems or directly contacting building security/supervisor.\", \"Challenging the individual verbally while maintaining safe distance and awareness of escape routes.\", \"Seeking immediate cover or egress while maintaining observation and preparing to report comprehensive details.\"]}}, \"title\": \"Unauthorized Access into Restricted Office Area\", \"injects\": null, \"scenario\": \"It is 6:15 PM on Monday at NATHANAEL BERNARDO STA. CATALINA, an office-type education facility. Most staff have left, but you are completing administrative tasks in a ground-floor office. You notice a person, unfamiliar to you, bypass the front desk and enter the main corridor. They avoid eye contact and move rapidly toward the secondary administrative area, which should be secured. Their pace quickens as they approach a door marked \'Staff Only\', attempting to open it.\", \"drillType\": \"micro\", \"objective\": \"To train staff on rapid recognition of unauthorized access, immediate activation of coordination, and initial control decisions during an early escalation moment within an office environment.\", \"teamRoles\": null, \"outcomeMap\": {\"Verbal challenge and notify internal security via direct call.\": {\"tradeoff\": \"Gained a rapid attempt at direct control; introduced high personal exposure and an immediate risk of confrontation before backup is confirmed.\", \"riskLevel\": \"High personal exposure, Immediate control attempt, Moderate disruption, Subject likely to escalate\", \"consequence\": \"The individual pauses briefly, assessing your presence, then rapidly shifts direction or attempts to push past you towards the \'Staff Only\' area. Security is now being notified, but you are in close proximity to an unverified, escalating individual.\", \"likelyOutcome\": \"Within the next 60-120 seconds, the individual may become verbally aggressive or physically attempt to bypass you, moving into the restricted area. Your call to security provides some information, but they are not yet on scene to support your direct engagement.\", \"whyThisMatters\": \"Direct intervention without backup or strategic positioning significantly increases personal risk and reduces the capacity for a coordinated, controlled response.\", \"humanRealismNote\": \"The desire to directly address a breach and assert authority is common, aiming to solve the problem immediately, but often without full appreciation of the associated risks.\", \"coachingConnection\": \"Direct verbal challenge can rapidly escalate a situation, placing you in a high-exposure position before backup arrives or full situational awareness is established, increasing unpredictability.\"}, \"Maintain observation, discreetly document, and await further actions.\": {\"tradeoff\": \"Gained personal safety and avoided immediate confrontation; introduced a significant delay in organizational response and loss of situational awareness.\", \"riskLevel\": \"Low personal exposure, Delayed coordination, Operational disruption, Loss of control\", \"consequence\": \"The individual enters the \'Staff Only\' area without further interruption, now out of your direct line of sight. No formal alert has been initiated, and the response chain remains inactive. The exact location and intent of the individual are now unknown.\", \"likelyOutcome\": \"Within the next 60-120 seconds, the individual is deeper within the restricted area, potentially accessing sensitive information or encountering other staff. Without a formal alert, building security remains unaware, and critical response time is lost.\", \"whyThisMatters\": \"Passive observation without an immediate trigger for escalation allows an unauthorized individual to gain unchecked access, increasing overall risk and organizational liability.\", \"humanRealismNote\": \"There\'s a natural tendency to avoid confrontation, hoping the situation will resolve itself or waiting for more definitive proof of threat, leading to hesitation.\", \"coachingConnection\": \"Delaying action and formal notification in an already escalating situation allows the threat to deepen, reducing control over the environment and complicating later intervention efforts.\"}, \"Activate emergency alert system (if appropriate to your facility) and retreat to a secure location.\": {\"tradeoff\": \"Gained immediate organizational awareness and reduced personal exposure; introduced a potential for the individual to accelerate movement or seek deeper concealment.\", \"riskLevel\": \"Low personal exposure, Strong coordination, High disruption, Subject likely to evade\", \"consequence\": \"The alert system is activated, signaling building security and staff. The individual, hearing the alarm or noticing the increased activity, accelerates movement deeper into the facility, potentially seeking another exit or concealment. Containment is not yet established.\", \"likelyOutcome\": \"Within the next 60-120 seconds, building security and local law enforcement are en route. The individual may attempt to breach further interior doors or exit the building from another point. Your location is secure, but the individual\'s path remains unpredictable.\", \"whyThisMatters\": \"Early coordination initiates the professional response chain, increasing the likelihood of resolution while minimizing individual exposure, though direct containment may be delayed.\", \"humanRealismNote\": \"The instinct to prioritize personal safety and activate official protocols is strong, especially in an ambiguous but escalating situation, as it shifts responsibility to designated responders.\", \"coachingConnection\": \"Activating an alert rapidly prioritizes broad safety and coordination, enabling a structured response; however, it does not guarantee immediate direct control over the individual\'s movement.\"}}, \"exerciseType\": null, \"scenarioType\": \"Unauthorized Access\", \"responsePaths\": null, \"behavioralCues\": [\"Bypassing front desk\", \"Avoiding eye contact\", \"Accelerating movement towards restricted area\", \"Attempting to access a \'Staff Only\' door\"], \"guidedResponse\": null, \"durationMinutes\": 1.5, \"expectedOutcome\": {\"correctDecision\": \"Rapid activation of the response chain, potential for early interception, and reduced exposure for staff and assets.\", \"incorrectDecision\": \"Increased risk of direct confrontation, deeper penetration by the unauthorized individual, and delayed organized response due to lack of early notification.\"}, \"responseOptions\": null, \"commonBreakdowns\": [], \"debriefQuestions\": [], \"decisionBranches\": null, \"decisionPressure\": \"Rapid individual progression, lack of immediate clarity on intent, need for quick system activation under ambiguous circumstances.\", \"escalationMoment\": \"The individual\'s pace quickens as they actively move toward and attempt to access a door marked \'Staff Only\' within the ground-floor administrative area.\", \"expectedOutcomes\": [], \"facilitatorSetup\": null, \"participantRoles\": null, \"roleBasedActions\": [{\"role\": \"Staff\", \"action\": \"Immediately initiate an emergency alert (e.g., building security, supervisor hotline) while maintaining distance and identifying potential shelter options.\", \"rationale\": \"To activate the organizational response chain quickly and reduce personal exposure.\"}, {\"role\": \"Admin / Supervisor\", \"action\": \"Verify incident details, activate facility lockdown procedures if possible, and prepare to communicate with law enforcement upon notification.\", \"rationale\": \"To coordinate an escalated response and contain the situation, leveraging established protocols.\"}], \"roleSpecificCues\": null, \"scenarioTimeline\": null, \"criticalDecisions\": null, \"guidedCheckpoints\": null, \"communicationsFlow\": null, \"afterActionTemplate\": null, \"decisionCheckpoints\": null, \"primaryThreatSignal\": \"Unauthorized individual bypassing access control and progressing into restricted space.\", \"regulatoryAlignment\": [], \"documentationSection\": null, \"microDebriefQuestion\": \"What specific behavioral cues shifted this situation from \'unusual\' to \'action required\' for you, and how did these cues influence your immediate sense of urgency?\", \"preIncidentIndicator\": \"An unfamiliar individual bypassed the front desk in the multi-tenant building lobby, entered the main office corridor, and actively avoided eye contact with staff.\", \"executionInstructions\": [], \"communicationCheckpoints\": null, \"communicationRequirement\": {\"sender\": \"Staff\", \"message\": \"Unauthorized individual gaining access to restricted area. Description: [gender, height, clothing]. Last known location: ground floor, approaching \'Staff Only\' door.\", \"trigger\": \"Individual bypasses initial control point and progresses deeper into the facility.\", \"recipient\": \"Building Security & Supervisor\"}, \"compressedGuidedResponse\": {\"bestNextMove\": \"The most effective next move often involves activating the response chain immediately while maintaining distance and awareness, thereby reducing personal risk and enabling a coordinated professional response.\", \"criticalDecision\": \"The immediate decision is whether to prioritize direct engagement, rapid organizational alert, or structured observation that delays response but maintains cover.\", \"mostLikelyMistake\": \"A common mistake is assuming benign intent or waiting for a more explicit threat, which allows the unauthorized individual to gain significant ground or access.\", \"howAnExpertReadsThis\": [\"An expert identifies the combination of boundary violation, evasive movement, and directed progression towards a restricted area as critical indicators of an escalating threat requiring immediate action.\"]}}','[]'),(4,NULL,NULL,'micro',NULL,NULL,NULL,NULL,'2026-05-27 18:30:49','2026-05-27 18:30:49',1,1,'Evening Office Intruder - Education Facility',2,'Education','United States','system',NULL,'{\"actd\": {\"assess\": {\"whatToNotice\": [\"Unauthorized entry past a control point (reception gate).\", \"Non-compliance with verbal challenge and lack of response.\", \"Accelerated, purposeful movement deeper into restricted areas.\", \"Behavioral cues inconsistent with a legitimate visitor (no eye contact, no verbal interaction).\"], \"signalsThatMatter\": [\"Boundary violation combined with active evasion/non-compliance.\", \"Rapid forward progression into a more sensitive area of the facility.\", \"Lack of verbal or visual engagement indicating potential hostile intent.\"]}, \"commit\": {\"hesitationRisks\": [\"Increased penetration by the individual into secure areas.\", \"Greater risk to staff or faculty who may be present in those areas.\", \"Loss of control over the situation and reduced opportunity for early intervention.\"], \"decisionRequired\": \"Choose an immediate action to address the unauthorized, non-compliant individual progressing into restricted faculty offices, balancing personal safety with facility control.\"}, \"debrief\": {\"whatToImprove\": [\"Speed of recognition of boundary violation.\", \"Efficiency of emergency communication activation.\", \"Effectiveness of initial verbal challenge and de-escalation attempts (if applicable).\", \"Coordination with security protocols for internal lockdowns.\"], \"whatToDocument\": [\"Exact time and location of entry.\", \"Description of the individual (clothing, approximate age, distinguishing features).\", \"Observed behaviors (ignored verbal challenge, movement path, speed).\", \"Actions taken by staff and initial response.\"]}, \"takeAction\": {\"adaptabilityNote\": \"The chosen action must be adaptive to the individual\'s reaction. If initial engagement fails, immediate escalation to alert and safety protocols is critical. The primary goal is always to reduce exposure and activate resources.\", \"availableActions\": [\"Activate an alert and seek cover/safety.\", \"Verbally engage to demand they stop while preparing for an alert.\", \"Physically interpose to block progression while initiating an alert.\"]}}, \"title\": \"Evening Office Intruder - Education Facility\", \"scenario\": \"It\'s 5:15 PM, within evening operating hours, at the NATHANAEL BERNARDO STA. CATALINA office. Most staff have left, but a few remain. You are the administrative assistant at the front desk. An unknown individual, who is not recognized as staff or student, enters the reception area. They bypass the partially open security gate without pausing. When you ask, \'Can I help you?\', they offer no response, make no eye contact, and continue to accelerate down the main corridor towards the faculty office wing, which requires keycard access. The individual\'s movement is purposeful and shows no signs of hesitation.\", \"drillType\": \"micro\", \"objective\": \"To rapidly recognize unauthorized access and escalating behavior, and to commit to actions that initiate control and coordination.\", \"outcomeMap\": {\"Activate emergency alert and retreat to the nearest secure office.\": {\"tradeoff\": \"Gained personal safety and activated organizational response; introduced a delay in direct control over the individual\'s immediate progression.\", \"riskLevel\": \"Low personal exposure, Strong coordination, Low disruption, Subject likely to hesitate\", \"consequence\": \"The individual may briefly hesitate due to the alarm, but will likely continue moving deeper before security arrives. Your personal exposure is reduced, and the full response chain is actively engaged.\", \"likelyOutcome\": \"You move to a secure location, and the alert initiates. The individual proceeds further down the corridor for a short duration before security begins to close in. The situation remains dynamic, but resources are en route with a clear understanding of the threat.\", \"whyThisMatters\": \"This decision quickly mobilizes institutional resources while minimizing personal risk, setting up a coordinated containment effort.\", \"humanRealismNote\": \"This option prioritizes personal safety and institutional response, which can feel counter-intuitive to an instinct to \'do something directly.\'\", \"coachingConnection\": \"Prioritizing personal safety and activating the alert ensures organizational resources are mobilized, even if it means sacrificing immediate, direct control. This sets the stage for a coordinated, safer intervention by trained personnel.\"}, \"Verbally challenge them to stop while stepping partially into their path, preparing to call security.\": {\"tradeoff\": \"Gained a moderate attempt at direct control and verbal deterrence; introduced increased personal exposure and delayed formal coordination with security.\", \"riskLevel\": \"Moderate personal exposure, Delayed coordination, Moderate disruption, Subject likely to evade\", \"consequence\": \"The individual may briefly pause or attempt to bypass you, potentially increasing direct confrontation. While you attempt to gain control, the formal alert is delayed, allowing them to advance further.\", \"likelyOutcome\": \"You step into their path and issue a firm command. The individual sidesteps you or pushes past, continuing to advance. You are now in closer proximity, and the critical window for early security notification is rapidly closing as they near keycard-access areas.\", \"whyThisMatters\": \"This decision delays activation of the response chain, increasing personal exposure and allowing the individual to gain ground unhindered by institutional response.\", \"humanRealismNote\": \"A natural instinct is to verbally intervene or block. This response attempts to regain control directly, which can be effective but increases personal risk.\", \"coachingConnection\": \"Direct verbal engagement and positioning can be effective in some situations, but here, the individual has already shown non-compliance. Delaying the formal alert means resources are not yet mobilized, and the individual gains valuable time.\"}, \"Physically interpose directly in their path, loudly demanding they stop and identify themselves, attempting to activate a panic button.\": {\"tradeoff\": \"Gained an immediate, forceful attempt at direct control and alert activation; introduced critical personal exposure and a high risk of immediate confrontation.\", \"riskLevel\": \"High personal exposure, Immediate control attempt, High disruption, Subject likely to escalate\", \"consequence\": \"Direct physical interposition against an unknown, non-compliant individual carries significant personal risk and could provoke an immediate physical escalation. The panic button activates an alert, but your personal safety is immediately compromised.\", \"likelyOutcome\": \"You physically block the individual\'s path. They react with aggression, pushing past you or directly confronting you. The panic button may or may not activate successfully, but you are now in a high-risk situation with no immediate backup. The situation has escalated rapidly.\", \"whyThisMatters\": \"This decision immediately escalates personal exposure and confrontation risk without confirming the activation of coordinated support, creating an uncontrolled, high-threat situation.\", \"humanRealismNote\": \"The urge to protect the space or stop the individual can lead to actions with high personal risk, especially when feeling responsible.\", \"coachingConnection\": \"While immediate control is desirable, direct physical confrontation with an unknown, non-compliant individual can rapidly escalate the threat, putting you in extreme danger. Prioritizing activation and safety allows trained personnel to manage the direct confrontation.\"}}, \"scenarioType\": \"Unauthorized Access\", \"behavioralCues\": [\"Bypassing reception gate\", \"Ignoring verbal greeting/challenge\", \"Accelerating movement deeper into the facility\", \"Lack of eye contact or verbal response\"], \"guidedResponse\": null, \"durationMinutes\": 2, \"expectedOutcome\": {\"correctDecision\": \"Activation of the response chain allows for rapid interception and potential containment, minimizing the intruder\'s penetration into restricted areas.\", \"incorrectDecision\": \"Delaying the alert or attempting solo intervention without backup allows the intruder to gain deeper access, increasing risk to occupants and potential loss of control.\"}, \"responseOptions\": null, \"commonBreakdowns\": [\"Hesitation due to \'social proof\' or fear of overreacting.\", \"Attempting solo intervention without appropriate training or backup.\", \"Delaying critical communication to security or supervisors.\"], \"debriefQuestions\": [\"What specific behavioral cues made this situation escalate from \'suspicious\' to \'requiring immediate action\'?\", \"What is the most immediate threat presented by the individual\'s actions?\", \"How does your chosen action impact the safety of others in the faculty office wing?\", \"What information would be critical to communicate to first responders upon their arrival?\"], \"decisionPressure\": \"Ambiguity of intent, rapid progression, and lack of immediate backup.\", \"escalationMoment\": \"The individual, without making eye contact or responding to the administrative assistant\'s polite \'Can I help you?\', quickly moved past the reception area and is now accelerating down the main corridor towards the faculty office wing, which requires keycard access.\", \"expectedOutcomes\": [\"Rapid activation of facility security protocols and emergency response.\", \"Minimization of unauthorized access depth into restricted areas.\", \"Protection of remaining staff and faculty within the building.\"], \"roleBasedActions\": [{\"role\": \"Administrative Assistant\", \"action\": \"Activate the emergency alert system and retreat to the nearest secure office.\", \"rationale\": \"Prioritizes personal safety, initiates a coordinated response, and limits further unauthorized access.\"}, {\"role\": \"Security/Supervisor (remotely)\", \"action\": \"Dispatch immediate response team to the faculty office wing and initiate remote lockdown procedures for internal doors.\", \"rationale\": \"Contains the threat, limits forward progression, and protects occupants in affected areas.\"}], \"primaryThreatSignal\": \"Unauthorized access, non-compliance, and forward progression into restricted space.\", \"regulatoryAlignment\": [\"OSHA General Duty Clause for workplace safety\", \"Local emergency management guidelines for educational facilities\", \"Campus security and incident response policies\"], \"microDebriefQuestion\": \"What specific indicators shifted your assessment from \'suspicious\' to \'active threat requiring immediate action\'?\", \"preIncidentIndicator\": \"An unknown individual entered the main reception area of the NATHANAEL BERNARDO STA. CATALINA office building at 5:15 PM, after regular public operating hours (5-7pm operating hours). They bypassed the partially open reception gate without acknowledging the administrative assistant at the front desk.\", \"executionInstructions\": [\"Read the scenario carefully.\", \"Select the immediate action you would take as the administrative assistant.\", \"Review the consequences of your decision.\"], \"communicationRequirement\": {\"sender\": \"Administrative Assistant\", \"message\": \"Unauthorized individual, non-compliant, moving to faculty offices. No response to verbal challenge.\", \"trigger\": \"Individual moves past reception after verbal challenge is ignored.\", \"recipient\": \"Campus Security / Supervisor\"}, \"compressedGuidedResponse\": {\"bestNextMove\": \"Activate the organizational emergency response system while moving to a position of cover or safety to reduce personal exposure and enable rapid, coordinated intervention.\", \"criticalDecision\": \"The immediate decision is whether to prioritize personal safety and early coordination, or attempt direct intervention with increased personal risk.\", \"mostLikelyMistake\": \"Delaying the alert or attempting direct, solitary intervention against a non-compliant individual, allowing them to gain control of space.\", \"howAnExpertReadsThis\": [\"The individual\'s behavior (bypassing, ignoring, accelerating) signals hostile intent and an immediate threat, not benign confusion. Their progression deeper into a restricted area is critical.\"]}}','[\"OSHA General Duty Clause for workplace safety\", \"Local emergency management guidelines for educational facilities\", \"Campus security and incident response policies\"]'),(5,NULL,NULL,'micro',NULL,NULL,NULL,NULL,'2026-05-27 18:33:48','2026-05-27 18:33:48',1,1,'Active Threat in Academic Wing',2,'Education','United States','user','You\'re working at your desk and you hear the fire alarm sound and as you are getting ready to get up and leave you hear somebody screaming he has a gun, you think they are in the office next to you what do you do','{\"actd\": {\"assess\": {\"whatToNotice\": [\"Conflicting auditory signals: fire alarm vs. scream of \'He has a gun!\'\", \"Proximity of the scream indicating immediate danger in an adjacent, accessible space.\", \"The nature of the threat (armed intruder) supersedes a standard fire evacuation protocol.\"], \"signalsThatMatter\": [\"The explicit verbalization of \'He has a gun!\' as a primary, overriding threat indicator.\", \"The sound\'s location indicating forward progression into the building\'s controlled space.\", \"The fire alarm now functions as a potential distraction or means to funnel occupants.\"]}, \"commit\": {\"hesitationRisks\": [\"Delaying action due to ambiguity or social proof (others evacuating for fire alarm).\", \"Misinterpreting the scream as part of a drill or a non-credible event.\", \"Underestimating the immediate and escalating nature of an armed threat.\"], \"decisionRequired\": \"An immediate decision to secure current position, attempt escape, or directly investigate the threat, despite the fire alarm.\"}, \"debrief\": {\"whatToImprove\": [\"Rapid threat recognition under conflicting cues.\", \"Overriding instinctual responses (evacuation) with threat-appropriate actions (shelter/report).\", \"Effective and concise communication of critical details to emergency services.\"], \"whatToDocument\": [\"Exact time and nature of the audible threat (\'He has a gun!\').\", \"Specific location of the perceived threat and direction of movement.\", \"Actions taken to secure personal space and initiate communication with authorities.\"]}, \"takeAction\": {\"adaptabilityNote\": \"Actions must adapt to the primary threat (active shooter), overriding standard fire alarm procedures. Situational awareness dictates a shelter-in-place and report strategy in this close proximity.\", \"availableActions\": [\"Lock down and take cover, reporting the threat.\", \"Attempt immediate evacuation.\", \"Directly engage or observe the source of the scream.\"]}}, \"title\": \"Active Threat in Academic Wing\", \"scenario\": \"You are a faculty member working at your desk in a university building. The fire alarm sounds, prompting you to begin gathering your belongings for evacuation. Suddenly, a loud, distinct scream from the adjacent office corridor pierces through the alarm: \'He has a gun!\' The sounds suggest the individual is moving deeper into the academic wing, and you believe they are in the office next to you.\", \"drillType\": \"micro\", \"objective\": \"To rapidly assess conflicting threat indicators and commit to an immediate, protective action and coordination response.\", \"outcomeMap\": {\"Move quickly to evacuate via the nearest exit, alerting anyone you encounter.\": {\"tradeoff\": \"Gained potential for self-extraction; introduced high personal exposure and unpredictable encounters within the threat area.\", \"riskLevel\": \"Elevated Risk\", \"consequence\": \"By evacuating, you introduce yourself to the unknown path of the threat. While you may alert others, you risk encountering the armed individual directly in an uncontrolled environment, increasing your exposure and potentially compromising others attempting to shelter.\", \"likelyOutcome\": \"As you move into the hallway, you may encounter other confused occupants, some evacuating for the fire alarm, others now aware of the scream. The armed individual may be progressing towards your exit route or already past it, leaving you exposed in the open. The formal response chain is not yet directly informed of your specific movement or the threat\'s exact location.\", \"whyThisMatters\": \"This decision sacrifices the safety of a secured space for an uncertain escape path, directly increasing personal risk and delaying effective coordination.\", \"humanRealismNote\": \"The urge to escape is powerful, especially during an alarm. However, an immediate, unverified evacuation during an active threat can lead to direct confrontation, a natural human error under intense stress.\", \"coachingConnection\": \"While escape is a valid tactic when the path is clear, moving blindly into an escalating threat environment dramatically increases personal exposure and organizational liability. It bypasses the formal coordination chain, leaving responders with less information.\"}, \"Activate door lock, turn off lights, seek cover, and call 911/Campus Security.\": {\"tradeoff\": \"Gained immediate personal safety and initiated formal coordination; introduced a delay in direct intervention, but from a secure position.\", \"riskLevel\": \"Lowest Risk Response\", \"consequence\": \"You establish a secure, defensible position, reducing your immediate personal exposure. You are isolated from the direct threat path and can relay critical, real-time information to first responders. Your office space becomes a point of safety rather than a vulnerability.\", \"likelyOutcome\": \"The response chain is now active, with security and law enforcement receiving critical intelligence. The individual continues to move through the building, but your immediate space is secure, and you are no longer in their direct, unobserved path. Containment efforts are in motion, though the precise location of the threat remains dynamic.\", \"whyThisMatters\": \"This decision immediately activates a coordinated response while maximizing personal safety, directly influencing the trajectory of the entire incident towards containment and resolution.\", \"humanRealismNote\": \"This option acknowledges the natural instinct to \'do something\' but channels it into protective, coordinated action rather than impulsive, high-risk confrontation. Overcoming the instinct to evacuate during a fire alarm requires deliberate threat assessment.\", \"coachingConnection\": \"This choice prioritizes life preservation and coordination, which are foundational to reducing liability and improving survivability. Delaying this action increases exposure and organizational risk by failing to activate the response chain early.\"}, \"Open your office door carefully to assess the situation directly, then decide.\": {\"tradeoff\": \"Gained direct, but highly dangerous, visual information; introduced critical personal exposure and increased the likelihood of direct engagement.\", \"riskLevel\": \"Critical Risk\", \"consequence\": \"Opening your door places you directly in harm\'s way, exposing yourself to immediate and potentially lethal confrontation with the armed individual. This action forfeits your current cover, offers no control, and critically delays the activation of protective measures.\", \"likelyOutcome\": \"You open your door slightly, exposing yourself to the corridor. You may see the individual, potentially drawing their attention directly to your position, or you may be met with an immediate hostile action. Your brief assessment has bypassed any opportunity to secure your space and activate the emergency response chain, making you a primary target.\", \"whyThisMatters\": \"This decision immediately elevates personal risk to a critical level, sacrificing all protective measures for direct observation, severely compromising safety and delaying organized response.\", \"humanRealismNote\": \"The desire for more information is a common human response to ambiguity. However, in an active threat, this can be a fatal delay, as curiosity can override safety instincts.\", \"coachingConnection\": \"This action introduces critical personal exposure and compromises immediate control over your environment, directly conflicting with the core principles of preserving life and maintaining spatial control during an active threat. It also delays coordination by prioritizing personal assessment over immediate notification.\"}}, \"scenarioType\": \"Active Threat\", \"behavioralCues\": [\"Scream of \'He has a gun!\'\", \"Auditory proximity of the threat in the adjacent corridor\", \"Fire alarm as a potential deceptive tactic or concurrent event\"], \"guidedResponse\": null, \"durationMinutes\": 2, \"expectedOutcome\": {\"correctDecision\": \"Rapid activation of shelter-in-place protocols and the formal response chain, minimizing personal exposure and enabling timely professional intervention.\", \"incorrectDecision\": \"Increased personal exposure, delayed formal response, and potential for misdirection due to the fire alarm.\"}, \"responseOptions\": null, \"commonBreakdowns\": [\"Hesitation due to conflicting information (fire alarm).\", \"Assuming the threat is not real or will resolve itself.\", \"Attempting to evacuate directly into an unknown threat path.\", \"Prioritizing observation over immediate protective action.\"], \"debriefQuestions\": [\"What specific cues shifted your perception from a fire alarm to an active threat?\", \"How did the fire alarm complicate your immediate decision-making process?\", \"What is the primary risk associated with choosing to evacuate when an active threat is confirmed nearby?\"], \"decisionPressure\": \"Immediate and ambiguous threat with conflicting signals (fire alarm vs. active threat report).\", \"escalationMoment\": \"A loud, distinct scream of \'He has a gun!\' from the adjacent office corridor.\", \"expectedOutcomes\": [\"Participants will demonstrate rapid threat recognition.\", \"Participants will prioritize securing their immediate environment.\", \"Participants will initiate appropriate communication protocols under stress.\"], \"roleBasedActions\": [{\"role\": \"Staff (Faculty)\", \"action\": \"Secure personal space, seek cover, and report the threat.\", \"rationale\": \"Prioritize personal safety and immediate activation of the formal response chain.\"}, {\"role\": \"Responder / Security\", \"action\": \"Locate and contain the threat, coordinate with law enforcement, and facilitate evacuation/shelter.\", \"rationale\": \"Rapid intervention to mitigate harm and control the incident.\"}, {\"role\": \"Admin / Supervisor\", \"action\": \"Activate emergency communication systems, account for personnel, and provide critical information to responders.\", \"rationale\": \"Ensure broad notification and support coordinated organizational response.\"}], \"primaryThreatSignal\": \"Verbal report of an armed individual in close proximity, overriding a facility alarm.\", \"regulatoryAlignment\": [\"NIMS/ICS principles for incident management adaptation.\", \"OSHA General Duty Clause for workplace violence prevention.\", \"Clery Act guidance on campus safety and emergency response.\"], \"microDebriefQuestion\": \"What was the single most critical piece of information that shifted your decision from fire evacuation to active threat response?\", \"preIncidentIndicator\": \"Fire alarm sounding throughout the university building.\", \"executionInstructions\": [\"Read the scenario carefully.\", \"Select the immediate action you would take.\", \"Review the consequences and expert coaching for your chosen action.\"], \"communicationRequirement\": {\"sender\": \"Faculty member (Participant)\", \"message\": \"Active threat with a gun, immediate office corridor, Fire alarm is a distraction. I am securing my office [Building/Room].\", \"trigger\": \"Confirmation of an active threat (hearing \'He has a gun!\')\", \"recipient\": \"911 / Campus Security\"}, \"compressedGuidedResponse\": {\"bestNextMove\": \"Immediately secure your office door, take cover, and contact 911/Campus Security with a clear, concise report of the active threat and fire alarm.\", \"criticalDecision\": \"The immediate choice is between securing your current location and reporting, or attempting to evacuate/assess, directly impacting personal safety and response timing.\", \"mostLikelyMistake\": \"Attempting to evacuate due to the fire alarm or trying to visually confirm the threat, both of which increase personal exposure.\", \"howAnExpertReadsThis\": [\"The combination of a fire alarm and a credible active threat report creates a high-ambiguity, high-pressure scenario where primary threat assessment must override standard emergency protocols. The scream \'He has a gun!\' is the definitive escalation.\"]}}','[\"NIMS/ICS principles for incident management adaptation.\", \"OSHA General Duty Clause for workplace violence prevention.\", \"Clery Act guidance on campus safety and emergency response.\"]');
