INSERT INTO `incident_reports` VALUES (8,2,'Mainstreet Retailers','threatening_behavior','moderate','2026-05-28 00:00:00','Parking Lot','I was approached by a former employee who was asking me to scan them into the building.  I said no, but then he made a threat towards me that if I didn\'t help him I would be on his \"list\".  I immediately walked in through the west side employee entrance and closed the door behind me.  ','Dave (former employee) ','None, but should be on the security camera',0,0,'Employee',NULL,'under_review','test',214,'2026-06-01 19:42:52','K9StO3FzE58-bfef','2026-05-28 16:48:49','2026-06-01 19:42:52',0,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL),(9,1,'NATHANAEL BERNARDO STA. CATALINA','threatening_behavior','low','2026-05-21 00:00:00','test','testetwtwet','asdasdas','asdasdas',1,1,'Patient / Client',NULL,'new',NULL,NULL,NULL,'d90bGQ0KHyPSMcut','2026-05-28 17:49:59','2026-05-28 17:49:59',1,'skin_disorder','Leg(s)','werwer','first_aid_only',1,1,1,1,1,'asdasd','asdasd','2026-05-26','2026-05-19','asdasdasd',1,1,NULL,1,'in_person',NULL,'asdasdasd',0,NULL,NULL,NULL,NULL),(10,2,'Mainstreet Retailers','threatening_behavior','moderate','2026-05-27 00:00:00','Parking Lot','test test test ',NULL,NULL,0,0,'Employee',NULL,'referred',NULL,214,'2026-05-28 19:07:20','S3t7mIvVlv7mGIoD','2026-05-28 19:06:25','2026-05-28 19:07:19',0,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,0,0,NULL,0,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL),(11,2,'Mainstreet Retailers','threatening_behavior','moderate','2026-05-29 00:00:00','Lobby','Test test test',NULL,NULL,0,0,'Employee',NULL,'under_review','test',1,'2026-06-10 17:36:07','faUAhgnw1KllRF2w','2026-05-29 18:56:43','2026-06-10 17:36:07',0,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,0,0,NULL,1,'phone',NULL,NULL,0,NULL,NULL,NULL,NULL),(12,2,'Mainstreet Retailers','threatening_behavior','moderate','2026-06-01 00:00:00','Parking Lot','te